import { Directive, ViewContainerRef, AfterViewInit, TemplateRef, ChangeDetectorRef, Input } from '@angular/core';

@Directive({
  selector: '[hgDeferOnVisible]'
})
export class DeferOnVisibleDirective implements AfterViewInit {
  @Input() hgDeferOnVisiblePlaceHolderClass: string;

  private observer!: IntersectionObserver;
  private hasLoaded = false;

  constructor(
    private templateRef: TemplateRef<any>,
    private viewContainer: ViewContainerRef,
    private cdRef: ChangeDetectorRef
  ) {}

  ngAfterViewInit() {
    const placeholder = document.createElement('span');
    if (!!this.hgDeferOnVisiblePlaceHolderClass) {
      placeholder.classList.add(this.hgDeferOnVisiblePlaceHolderClass);
    }

    this.viewContainer.element.nativeElement.parentNode.insertBefore(
      placeholder,
      this.viewContainer.element.nativeElement
    );

    this.observer = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && !this.hasLoaded) {
        this.viewContainer.createEmbeddedView(this.templateRef);
        this.hasLoaded = true;

        this.observer.disconnect();
        placeholder.remove();

        this.cdRef.markForCheck();
      }
    });

    this.observer.observe(placeholder);
  }
}
