import { ChangeDetectionStrategy, Component } from '@angular/core';
import { Observable } from 'rxjs';
import { take } from 'rxjs/operators';
import { DialogService } from '@honoregaming/core';
import { AuthService, SmarticoService } from '@honoregaming/customer-core';
import { DpType } from 'projects/customer/hg-core/src/lib/models/smartico-sdk.model';

type TrailParticle = {
  index: number;
  opacity: number;
  animationDelay: number;
};

@Component({
  selector: 'hg-smartico-missions-banner',
  templateUrl: './smartico-missions-banner.component.html',
  styleUrls: ['./smartico-missions-banner.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SmarticoMissionsBannerComponent {
  readonly trailLength: number = 200;
  readonly trailSpreadSeconds: number = 2;
  readonly trailMiddleBand: number = 0.333;
  readonly trailParticles: ReadonlyArray<TrailParticle> = Object.freeze(
    Array.from({ length: this.trailLength }, (_, index) => {
      const position: number = index / (this.trailLength - 1);
      const distanceFromMiddle: number = Math.abs(position - 0.5);
      const halfBand: number = this.trailMiddleBand / 2;
      return {
        index: index,
        animationDelay: -((this.trailLength - 1 - index) / (this.trailLength - 1)) * this.trailSpreadSeconds,
        opacity: distanceFromMiddle <= halfBand ? 1 : 1 - (distanceFromMiddle - halfBand) / (0.5 - halfBand)
      };
    })
  );

  missionsCount$: Observable<number> = this.smarticoService.missionsCount$;

  constructor(
    private readonly smarticoService: SmarticoService,
    private readonly authService: AuthService,
    private readonly dialogService: DialogService
  ) {}

  onClick(): void {
    this.authService.status$.pipe(take(1)).subscribe(status => {
      if (status === 'connected') {
        this.smarticoService.executeDeepLink(DpType.Missions);
      } else {
        this.dialogService.toggleDialog('login', true);
      }
    });
  }

  particleTrackByIndex(_: number, particle: TrailParticle): number {
    return particle.index;
  }
}
