import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { BetType } from '@honoregaming/types';

@Component({
  selector: 'hg-bet-types',
  templateUrl: './bet-types.component.html',
  styleUrls: ['./bet-types.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetTypesComponent {
  @Input()
  betTypes: BetType[];
  @Input()
  selectedBetTypeId: number;

  @Output()
  betTypeSelected = new EventEmitter<BetType>();

  constructor() {}

  selectBetType(betType: BetType) {
    this.betTypeSelected.emit(betType);
  }

  trackBetType(_index: number, betType: BetType) {
    return betType.id;
  }
}
