import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Input,
  OnChanges,
  EventEmitter,
  Output
} from '@angular/core';

import { Async, BroadcastingService, PushService, BetLinesMapperService } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { Match, EventWithEventBetTypes, EventBetType } from '@honoregaming/types';
import { BetSlipBetLinesService, BetSlipService } from '@honoregaming/betslip';
import { EventsMapperService, EventsService, FetchEventBetTypesMode } from '@honoregaming/events';
import { EventsWithEventBetTypesComponentBase } from '@honoregaming/sports-ui';
import { merge } from 'rxjs';
import { takeUntil, skip } from 'rxjs/operators';

@Component({
  selector: 'hg-next-live',
  templateUrl: './next-live.component.html',
  styleUrls: ['./next-live.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class NextLiveComponent extends EventsWithEventBetTypesComponentBase implements OnChanges {
  @Input() entryPointId: number | undefined;
  @Output() loaded = new EventEmitter<void>();

  isLoaded = false;

  constructor(
    private eventsService: EventsService,
    protected i18nService: I18nService,
    protected betSlipService: BetSlipService,
    protected cdRef: ChangeDetectorRef,
    protected pushService: PushService,
    protected bcService: BroadcastingService,
    protected eventsMapperService: EventsMapperService,
    protected betLinesMapperService: BetLinesMapperService,
    protected betSlipBetLinesService: BetSlipBetLinesService
  ) {
    super(
      i18nService,
      betSlipService,
      pushService,
      cdRef,
      bcService,
      eventsMapperService,
      betLinesMapperService,
      betSlipBetLinesService
    );
  }

  ngOnChanges() {
    super.ngOnInit();
    this.loadNextLiveEvents(this.entryPointId);
  }

  trackByFn(_index: number, item: EventWithEventBetTypes<Match, EventBetType>) {
    return item.id;
  }

  @Async()
  private loadNextLiveEvents(entryPointId?: number) {
    this.eventsService
      .getNextSportsEvents(null, null, FetchEventBetTypesMode.Default, entryPointId, true)
      .pipe(takeUntil(merge(this.destroy$, this.i18nService.languageChanged$.pipe(skip(1)))))
      .subscribe(events => {
        this.events = events.result;
        this.updateEventsSubscriptions();
        this.loaded.emit();
        this.isLoaded = true;
      });
  }
}
