import {
  Component,
  ChangeDetectionStrategy,
  Input,
  EventEmitter,
  Output,
  ChangeDetectorRef,
  OnChanges
} from '@angular/core';
import { EventBetTypeItem, SelectableEventBetTypeItem, Match, EventBetType } from '@honoregaming/types';
import { Subscription } from 'rxjs';
import { transition, style, animate, trigger } from '@angular/animations';
import { EventStateType, EventStateDetailsType } from '@honoregaming/types';
import { UrlFriendlyGeneratorService } from '@honoregaming/ui';

@Component({
  selector: 'hg-live-event-with-event-bet-type-item',
  templateUrl: './live-event-with-event-bet-type-item.component.html',
  styleUrls: ['./live-event-with-event-bet-type-item.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('disabled', [
      transition('void => *', [
        style({ opacity: '0', transform: 'scale(0)' }),
        animate('0.2s ease-in', style({ opacity: '1', transform: 'scale(1)' }))
      ]),
      transition('* => void', animate('0.2s ease-in', style({ opacity: '0', transform: 'scale(0)' })))
    ])
  ]
})
export class LiveEventWithEventBetTypeItemComponent implements OnChanges {
  @Input()
  event: Match;
  @Input()
  eventBetType: EventBetType;
  @Input()
  isLoadingOdds: boolean = false;

  @Output()
  betSelectionChanged = new EventEmitter<{
    item: EventBetTypeItem;
    selected: boolean;
  }>();
  subscription: Subscription;
  disabled: boolean;

  EventStateDetailsType = EventStateDetailsType;
  EventStateType = EventStateType;

  urlFriendlyHomeTeamName: string;
  urlFriendlyAwayTeamName: string;

  constructor(private cdRef: ChangeDetectorRef, private urlFriendlyGeneratorService: UrlFriendlyGeneratorService) {}

  ngOnChanges() {
    this.disabled = this.event.state !== EventStateType.Started;
    this.urlFriendlyHomeTeamName = this.urlFriendlyGeneratorService.getUrlFriendlyText(this.event.homeTeamName);
    this.urlFriendlyAwayTeamName = this.urlFriendlyGeneratorService.getUrlFriendlyText(this.event.awayTeamName);
    this.cdRef.markForCheck();
  }

  toggleBet(item: SelectableEventBetTypeItem) {
    if (
      !item.odds ||
      item.odds <= 1 ||
      !item.active ||
      !item.bettingAllowed ||
      !this.eventBetType.active ||
      !this.eventBetType.bettingAllowed ||
      this.disabled ||
      item.completionDisabled
    ) {
      return;
    }

    this.betSelectionChanged.emit({
      item: item,
      selected: !item.selected
    });
  }

  trackEventBetTypeItem(_index, eventBetTypeItem: EventBetTypeItem) {
    return eventBetTypeItem.id;
  }

  get hasLongShortName(): boolean {
    const itemCount = this.eventBetType?.eventBetTypeItems?.length;

    if (itemCount === 3) {
      return this.eventBetType.eventBetTypeItems.some(item => item.shortName.length > 4);
    } else if (itemCount === 2) {
      return this.eventBetType.eventBetTypeItems.some(item => item.shortName.length > 10);
    } else {
      return false;
    }
  }
}
