import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  HostBinding,
  OnInit,
  Input,
  OnDestroy
} from '@angular/core';
import { merge } from 'rxjs';
import { DateTime } from 'luxon';
import { takeUntil, finalize, skip } from 'rxjs/operators';
import { Async, AsyncTrigger, DestroySubject } from '@honoregaming/core';
import { EventsService } from '@honoregaming/events';
import { I18nService } from '@honoregaming/i18n';
import { ContentService } from '@honoregaming/templating';
import { ManualOddsBoost } from '@honoregaming/types';
import { ManualOddsGroup } from 'projects/core/hg-types/models/odds-boost/manual-odds-group.model';
import { ManualOddsList } from 'projects/core/hg-types/models/odds-boost/manual-odds-list.model';

interface ListEntry {
  type: string;
  groupType?: string;
  id?: number;
  groupTitle?: string;
  iconUrl?: string;
  entryPointId?: number;
  headerLink?: string;
  date?: DateTime;
  list: (ManualOddsBoost & { selected: boolean })[];
}

@Component({
  selector: 'hg-manual-odds-boosts',
  templateUrl: './manual-odds-boosts.component.html',
  styleUrls: ['./manual-odds-boosts.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ManualOddsBoostsComponent extends DestroySubject implements OnInit, OnDestroy {
  @Input() @HostBinding('class.from-tab') fromTab: boolean = false;

  readonly TYPE_STANDALONE: string = 'TYPE_STANDALONE';
  readonly TYPE_GROUP: string = 'TYPE_GROUP';
  readonly FILTER_ALL: string = 'FILTER_ALL';
  readonly GROUP_TYPE_MATCH: string = 'GROUP_TYPE_MATCH';
  readonly GROUP_TYPE_COMBO: string = 'GROUP_TYPE_COMBO';
  readonly GROUP_TYPE_COMPETITION: string = 'GROUP_TYPE_COMPETITION';

  currentLanguage: string = this.i18nService.currentLanguageCode;
  fallbackLanguage: string = this.i18nService.fallbackLanguageCode;

  show: number = 3;
  manualOddsBoosts: (ManualOddsBoost & { selected: boolean; names: string })[] = [];

  manualOddsByEvent: {
    eventId?: number;
    showAll?: boolean;
    manualOddsList: (ManualOddsBoost & { selected: boolean })[];
  }[] = [];

  manualOddsAndGroups: ListEntry[] = [];
  displayedManualOddsAndGroups: ListEntry[] = [];
  selectedFilter: string = this.FILTER_ALL;
  matchCount: number = 0;
  comboCount: number = 0;
  competitionCount: number = 0;

  selectedManualOddsBoostIds: number[] = [];
  isLoading = false;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  hasFunbetsInformation: boolean = false;
  funbetInfosContent: string;
  funbetInfosStyle: string;

  constructor(
    private readonly eventsService: EventsService,
    private readonly i18nService: I18nService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly contentService: ContentService
  ) {
    super();
  }

  ngOnInit() {
    this.getManualOddsBoostInfos();
    this.getManualOddsBoosts();

    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(l => {
      this.currentLanguage = l;
      this.cdRef.markForCheck();
    });
  }

  @Async()
  getManualOddsBoostInfos() {
    this.contentService
      .getContent('infos-funbets')
      .pipe(takeUntil(merge(this.destroy$, this.i18nService.languageChanged$.pipe(skip(1)))))
      .subscribe(content => {
        if (content) {
          this.funbetInfosContent = content.content;
          this.funbetInfosStyle = content.style;
          this.hasFunbetsInformation = true;
        } else {
          this.hasFunbetsInformation = false;
        }
        this.cdRef.markForCheck();
      });
  }

  @Async()
  getManualOddsBoosts() {
    this.isLoading = true;
    this.eventsService
      .getManualOddsBoosts()
      .pipe(
        takeUntil(merge(this.destroy$, this.i18nService.languageChanged$.pipe(skip(1)))),
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(manualOddsBoosts => {
        this.manualOddsBoosts = manualOddsBoosts?.result.map(mob => {
          mob.names = JSON.parse(mob.localizedName ?? "''");
          mob.awayTeamNames = !!mob.localizedAwayTeamName ? JSON.parse(mob.localizedAwayTeamName) : {};
          mob.homeTeamNames = !!mob.localizedHomeTeamName ? JSON.parse(mob.localizedHomeTeamName) : {};

          return {
            ...mob,
            selected: false,
            active: true
          };
        });

        this.buildManualOddsGroups(manualOddsBoosts);
      });
  }

  buildManualOddsGroups(data: ManualOddsList): void {
    const newList: ListEntry[] = [];
    const sortedManualOdds: ManualOddsBoost[] = data.result.sort(
      (a, b) =>
        (b.expirationDate?.valueOf() ?? DateTime.fromISO(b.eventExpectedStart ?? '').valueOf()) -
        (a.expirationDate?.valueOf() ?? DateTime.fromISO(a.eventExpectedStart ?? '').valueOf())
    );
    for (let manualOdds of sortedManualOdds) {
      if (!manualOdds.oddsBoostGroupId && !manualOdds.eventId) {
        newList.push({
          type: this.TYPE_STANDALONE,
          list: [{ ...manualOdds, selected: false }]
        });
      } else {
        const id: number | undefined = manualOdds.oddsBoostGroupId ?? manualOdds.eventId;
        const manualOddsGroup: ManualOddsGroup | undefined = manualOdds.oddsBoostGroupId
          ? data.groups.find(group => group.id === manualOdds.oddsBoostGroupId)
          : undefined;
        manualOdds.group = manualOddsGroup;

        if (id) {
          const date: DateTime = manualOdds.expirationDate ?? DateTime.fromISO(manualOdds.eventExpectedStart ?? '');
          let group: ListEntry | undefined = newList.find(entry => entry.id === id && entry.date === date);
          if (!group) {
            group = {
              type: this.TYPE_GROUP,
              groupType: manualOddsGroup
                ? manualOddsGroup.eventCategory
                  ? this.GROUP_TYPE_COMPETITION
                  : this.GROUP_TYPE_COMBO
                : this.GROUP_TYPE_MATCH,
              id: id,
              groupTitle: manualOddsGroup
                ? manualOddsGroup.eventCategory
                  ? manualOddsGroup.name + ' : ' + manualOddsGroup.eventCategory.name
                  : manualOddsGroup.name
                : this.getTeamName(manualOdds.homeTeamNames, manualOdds.homeTeamName) +
                  ' - ' +
                  this.getTeamName(manualOdds.awayTeamNames, manualOdds.awayTeamName),
              iconUrl: manualOddsGroup?.iconUrl,
              entryPointId: !manualOddsGroup ? manualOdds.entryPointId : undefined,
              headerLink: manualOdds.eventId ? '/sports/event/' + manualOdds.eventId : undefined,
              date: date,
              list: []
            };

            newList.push(group);
          }

          group!.list.push({ ...manualOdds, selected: false });
        }
      }
    }

    this.manualOddsAndGroups = newList;
    this.displayedManualOddsAndGroups = this.manualOddsAndGroups;
    this.matchCount = this.manualOddsAndGroups.filter(entry => entry.groupType === this.GROUP_TYPE_MATCH).length;
    this.comboCount = this.manualOddsAndGroups.filter(entry => entry.groupType === this.GROUP_TYPE_COMBO).length;
    this.competitionCount = this.manualOddsAndGroups.filter(
      entry => entry.groupType === this.GROUP_TYPE_COMPETITION
    ).length;
  }

  filter(filter: string): void {
    this.displayedManualOddsAndGroups =
      filter === this.FILTER_ALL
        ? this.manualOddsAndGroups
        : this.manualOddsAndGroups.filter(entry => entry.groupType === filter);
    this.selectedFilter = filter;
  }

  getTeamName(names: { [key: string]: string }, fallbackName?: string): string | undefined {
    // Try to get local name
    let teamName = names[this.currentLanguage];

    // If empty | null | undefined, try fallback language > then plain name
    if (!teamName) {
      teamName = names[this.fallbackLanguage];
    }

    if (!teamName) {
      teamName = fallbackName;
    }

    return teamName;
  }
}
