import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  OnDestroy,
  Inject,
  ElementRef,
  ViewChildren,
  QueryList,
  HostListener,
  Optional,
  ViewChild
} from '@angular/core';
import { ActivatedRoute, Router, UrlSegment } from '@angular/router';
import { ReplaySubject, Observable, merge } from 'rxjs';
import { map, skip, takeUntil, finalize, take } from 'rxjs/operators';
import { I18nService } from '@honoregaming/i18n';
import {
  AsyncTrigger,
  Async,
  PushService,
  DestroySubject,
  kioskToken,
  updateEventBetTypeAfterPush,
  updateEventAfterPush,
  hasFlag,
  BroadcastingService,
  BetBuilderService,
  BetLinesMapperService
} from '@honoregaming/core';
import {
  PreEventOrLiveType,
  EventStateType,
  BetTypeGroup,
  SelectedItem,
  HomeOrAway,
  Match,
  SelectableEventBetTypeItem,
  EventBetType,
  EventBetTypeGroupedByBetType,
  EventWithEventBetTypes,
  EventBetTypeChangedModel,
  BetTypeKey
} from '@honoregaming/types';
import {
  IContainer,
  WidgetsService,
  customerOperatorConfigurationToken,
  CustomerOperatorConfiguration,
  TelemetryService,
  BannerService,
  getNameForEntryPoint,
  MessagesService
} from '@honoregaming/customer-core';
import { BetSlipService, BetSlipBetLinesService } from '@honoregaming/betslip';
import {
  EventsService,
  EventsMapperService,
  EventBetTypeGroupingService,
  EventBetTypeViewModelService,
  EventBetTypeGroupView
} from '@honoregaming/events';
import { Feature } from '@honoregaming/configuration';
import { GenericContentComponent, MessageService, Media, MediaService } from '@honoregaming/ui';
import { XupComponent } from '@honoregaming/customer-ui';
import { EventPageStickyHeaderService, StickyHeaderParams } from '@honoregaming/sports-event';
import { Images } from 'projects/core/hg-types/models/images.model';
import { BetBuilderTutorialComponent } from 'projects/customer/hg-customer-ui/src/lib/popins/bet-builder-tutorial/bet-builder-tutorial.component';
import { EventBetTypesFiltersComponent } from '../../components/event-bet-types-filters/event-bet-types-filters.component';

@Component({
  selector: 'hg-event-with-event-bet-types',
  templateUrl: './event-with-event-bet-types.container.html',
  styleUrls: ['./event-with-event-bet-types.container.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventWithEventBetTypesComponent extends DestroySubject implements OnInit, OnDestroy, IContainer {
  @AsyncTrigger() languageTrigger: Observable<string> = this.i18nService.languageChanged$;

  @ViewChildren('ebtiListContainer') set setMyElement(elements: QueryList<ElementRef>) {
    this.processElementHeights(elements);
  }
  @ViewChild('scoreWidget', { read: ElementRef }) scoreWidgetElement?: ElementRef;
  @ViewChild('eventBetTypeFilters') eventBetTypesFiltersComponent?: EventBetTypesFiltersComponent;

  private static readonly THREE_WAY_BET_IDS: number[] = [BetTypeKey.OneXTwo, BetTypeKey.OneXTwoLive];
  private static readonly TWO_WAY_BET_IDS: number[] = [BetTypeKey.OneTwo, BetTypeKey.OneTwoLive];
  private static readonly NEW_PLAYER_STATS_BET_TYPE_ID: number = BetTypeKey.ShotsAttempted;

  private readonly BATCH_SIZE: number = 10;
  private readonly COLLAPSE_THRESHOLD: number = 180;

  readonly EventStateType: typeof EventStateType = EventStateType;
  readonly PreEventOrLiveType: typeof PreEventOrLiveType = PreEventOrLiveType;
  readonly HomeOrAway: typeof HomeOrAway = HomeOrAway;
  readonly BetTypeGroup: typeof BetTypeGroup = BetTypeGroup;

  eventId?: number;
  event?: Match;

  eventBetTypesGroupedByBetType: EventBetTypeGroupedByBetType[] = [];
  filteredEventBetTypesGroupedByBetType: EventBetTypeGroupedByBetType[] = [];
  renderedGroups: EventBetTypeGroupView[] = [];
  enrichedGroups: EventBetTypeGroupView[] = [];
  filters: string[] = [];
  activeFilter: BetTypeGroup = BetTypeGroup.None;
  hasNewPlayerStatsBetType: boolean = false;
  betTypeIdsUsingTeamTemplate: Set<number> = new Set();
  teamGroupedItemsByBetType?: Record<number, Record<HomeOrAway, EventBetType[]>>;

  selectedItems: SelectedItem[] = [];

  loading: boolean = false;
  isStickyHeader: boolean = false;
  isStickyFilters: boolean = false;
  hasStatsDisplayed: boolean = false;
  isLiveEvent: boolean = false;

  betBuilderBannerImages?: Images;
  isBetBuilderToggled: boolean = false;
  isLoadingOdds: boolean = false;

  eventBetGroupsHeight: number = 0;
  blockEventHeight?: number;
  blockEventMobileHeight?: number;
  scoreWidgetInitalHeight?: number;

  hasManualOddsFeature: boolean = this.operatorConfiguration.operatorFeatures.includes(Feature.ManualOdds);
  warnOnDataConsumption: boolean = this.operatorConfiguration.onlineConfiguration?.warnOnDataConsumption;
  lmtAllowedEntryPoints: number[] =
    this.operatorConfiguration.scoreWidgetConfiguration?.configuration?.liveMatchTrackerAllowedEntryPoints ?? [];
  currentLanguage: string = this.i18nService.currentLanguageCode;
  fixedSportEventHeader: boolean = this.operatorConfiguration.onlineConfiguration?.fixedSportEventHeader;
  useXupThemeBg: boolean =
    this.operatorConfiguration.themeCustomizationConfiguration?.displayCustomizedXUPBettypeOperatorThemeBackground;

  countMessages?: number;

  private subscriptionSubject?: ReplaySubject<void> = new ReplaySubject<void>(1);
  private skipNextUpdate: boolean = false;
  private scrollTicking: boolean = false;

  constructor(
    private readonly i18nService: I18nService,
    private readonly route: ActivatedRoute,
    private readonly router: Router,
    private readonly betSlipService: BetSlipService,
    private readonly eventsService: EventsService,
    private readonly eventsMapperService: EventsMapperService,
    private readonly pushService: PushService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly bcService: BroadcastingService,
    private readonly widgetsService: WidgetsService,
    private readonly telemetryService: TelemetryService,
    private readonly bannerService: BannerService,
    private readonly messageService: MessageService,
    private readonly messagesService: MessagesService,
    private readonly hostRef: ElementRef,
    private readonly eventBetTypeGroupingService: EventBetTypeGroupingService,
    private readonly eventPageStickyHeaderService: EventPageStickyHeaderService,
    private readonly eventBetTypeViewModelService: EventBetTypeViewModelService,
    private readonly betBuilderService: BetBuilderService,
    private readonly betLinesService: BetLinesMapperService,
    private readonly betSlipBetLinesService: BetSlipBetLinesService,
    @Inject(customerOperatorConfigurationToken) public readonly operatorConfiguration: CustomerOperatorConfiguration,
    @Inject(kioskToken) public readonly isKiosk: boolean,
    @Optional() private readonly mediaService: MediaService
  ) {
    super();
  }

  ngOnInit(): void {
    this.initializeStickyHeader();
    this.initializeRouteHandling();
    this.initializeBetSlipSubscriptions();
    this.initializeLanguageHandling();
    this.subscribeToPushChanges();
    this.initializeMessagesCounter();
    this.listenOnLoadingOddsChanges();
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();
    this.bcService.broadcast('LMT.Widget.Hide');
    this.betBuilderService.toggleBetBuilder(false);
  }

  @HostListener('window:scroll')
  public scrollHandler(): void {
    if (!this.fixedSportEventHeader || this.scrollTicking) {
      return;
    }

    this.scrollTicking = true;
    requestAnimationFrame(() => {
      this.applyStickyState(this.mediaService.media);
      this.scrollTicking = false;
    });
  }

  trackEventBetType(_index: number, eventBetType: EventBetTypeGroupedByBetType): number {
    return eventBetType.betTypeId;
  }

  toggleEventBetTypeItem(eventBetType: EventBetType, eventBetTypeItem: SelectableEventBetTypeItem): void {
    if (
      !this.eventBetTypeGroupingService.isEventBetTypeItemToggleable(eventBetType, eventBetTypeItem, this.isLoadingOdds)
    ) {
      return;
    }

    this.betSlipBetLinesService
      .toggleEventBetTypeItem(this.event, eventBetType, eventBetTypeItem, !eventBetTypeItem.selected)
      .pipe(take(1))
      .subscribe((selected: boolean) => {
        if (eventBetTypeItem.selected && !selected) {
          this.selectedItems = this.selectedItems.filter(
            (selectedItem: SelectedItem) => selectedItem.eventBetTypeItemId !== eventBetTypeItem.id
          );
          this.updateSelectedItems();
        }
      });
  }

  getSubscription(): Observable<{
    eventSubscriptions: number[];
    betTypeSubscriptions: number[];
    betTypeByEventSubscriptions: number[];
  }> {
    return this.subscriptionSubject.pipe(
      map(() => ({
        eventSubscriptions: [this.event.id],
        betTypeSubscriptions: [],
        betTypeByEventSubscriptions: [this.event.id]
      }))
    );
  }

  onFilterChanged(event: { activeFilter: BetTypeGroup }): void {
    this.activeFilter = event.activeFilter;
    this.filter();

    if (this.isStickyHeader && window.pageYOffset > 0) {
      setTimeout(() => {
        window.scrollTo({ top: 0, left: 0, behavior: 'smooth' });
      }, 50);
    }
  }

  onWidgetDisplayed(type: string): void {
    this.widgetsService.addWidgetView(type).pipe(takeUntil(this.destroy$)).subscribe();

    if (this.isLiveWithFixedHeader()) {
      this.hasStatsDisplayed = true;
    }
  }

  onWidgetClosed(): void {
    if (this.isLiveWithFixedHeader()) {
      this.hasStatsDisplayed = false;
      this.applyStickyState(this.mediaService.media);
    }
  }

  onWidgetError(type: string): void {
    this.widgetsService.addWidgetErrorView(type).pipe(takeUntil(this.destroy$)).subscribe();
  }

  blockHeight(height: number): void {
    this.blockEventHeight = height;
  }

  setScoreWidgetHeight(): void {
    setTimeout(() => {
      this.scoreWidgetInitalHeight = this.scoreWidgetElement.nativeElement.offsetHeight;
    }, 0);
  }

  openCashoutPopup(betTypeId: number, eventBetTypeName: string): void {
    this.telemetryService.trackEvent('help_indicator_click_cashout', {
      market_id: betTypeId,
      market_name: eventBetTypeName
    });

    this.messageService.sendComponentMessage(GenericContentComponent, {
      title: this.i18nService.translateSync('EVENT.CASHOUT_POPUP.TITLE'),
      text: this.i18nService.translateSync('EVENT.CASHOUT_POPUP.CONTENT')
    });
  }

  toggleBetBuilder(isBetBuilderToggled: boolean): void {
    this.isBetBuilderToggled = isBetBuilderToggled;
    this.telemetryService.trackEvent('toggleBetBuilder', { isBetBuilderToggled });
    this.betBuilderService.toggleBetBuilder(isBetBuilderToggled);
    this.filter();
  }

  onBetBuilderBannerClicked(): void {
    this.bannerService.trackClick({
      name: 'bet_builder',
      id: 'bet_builder',
      page: 'sports_event'
    });
    this.openBetBuilderTutorial();
  }

  openXupPopup(betTypeContext: string | null | undefined): void {
    this.messageService
      .sendComponentMessage(XupComponent, {
        value: this.eventBetTypeViewModelService.getXupValue(betTypeContext)
      })
      .closed.pipe(takeUntil(this.destroy$))
      .subscribe();
  }

  loadMore(): void {
    const currentLength: number = this.renderedGroups.length;

    if (currentLength >= this.enrichedGroups.length) {
      return;
    }

    this.renderedGroups = this.enrichedGroups.slice(0, currentLength + this.BATCH_SIZE);
    this.cdRef.markForCheck();
  }

  private initializeStickyHeader(): void {
    if (!this.fixedSportEventHeader) {
      return;
    }
    this.mediaService?.media$.pipe(takeUntil(this.destroy$)).subscribe((media: Media) => this.applyStickyState(media));
  }

  private initializeRouteHandling(): void {
    this.route.params.pipe(takeUntil(this.destroy$)).subscribe((params: Record<string, string>) => {
      const eventId: number = this.extractEventId(params['event']);

      if (this.eventId !== eventId) {
        this.eventId = eventId;
        this.event = this.eventsService.getEventFromCache(this.eventId);
        this.isBetBuilderToggled = this.betBuilderService.isBetBuilderToggled;
        this.computeIsLive();
        this.loadData();
      }
    });
  }

  private extractEventId(eventParam: string): number {
    const matchIdGroups: RegExpExecArray = /^.*-m(\d+)$/.exec(eventParam);
    return matchIdGroups ? +matchIdGroups[1] : +eventParam;
  }

  private initializeBetSlipSubscriptions(): void {
    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(event => {
      if (this.skipNextUpdate) {
        this.skipNextUpdate = false;
        return;
      }

      this.selectedItems = this.betLinesService.betLinesToSelectedItems(event.lines);
      this.updateSelectedItems();
    });
  }

  private initializeLanguageHandling(): void {
    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe((language: string) => {
      this.currentLanguage = language;
      this.cdRef.markForCheck();
    });
  }

  private initializeMessagesCounter(): void {
    this.messagesService
      .getMessages()
      .pipe(takeUntil(this.destroy$))
      .subscribe(messages => {
        this.countMessages = messages.length;
      });

    this.betBuilderBannerImages = this.betBuilderService.bannerImages;
  }

  private subscribeToPushChanges(): void {
    this.subscribeToEventBetTypeChanges();
    this.subscribeToEventChanges();
  }

  private subscribeToEventBetTypeChanges(): void {
    this.pushService.eventBetTypeChanged$.pipe(takeUntil(this.destroy$)).subscribe(changed => {
      const hasBeenFound: boolean = this.applyEventBetTypeChange(changed);

      this.eventBetTypesGroupedByBetType = this.eventBetTypesGroupedByBetType.filter(
        (g: EventBetTypeGroupedByBetType) => g.eventBetTypes.length > 0
      );
      this.cdRef.markForCheck();

      if (!hasBeenFound && this.eventId === changed.eventId && changed.active) {
        this.handleNewEventBetType(changed);
      }
    });
  }

  private openBetBuilderTutorial(): void {
    this.messageService
      .sendComponentMessage(BetBuilderTutorialComponent, {}, { maxWidth: 500 })
      .closed.pipe(take(1))
      .subscribe(() => this.betBuilderService.validateBetBuilderTutorial());
  }

  private applyEventBetTypeChange(changed: EventBetTypeChangedModel): boolean {
    let hasBeenFound: boolean = false;

    this.eventBetTypesGroupedByBetType.forEach((group: EventBetTypeGroupedByBetType) => {
      const index: number = group.eventBetTypes.findIndex((ebt: EventBetType) => ebt.id === changed.eventBetTypeId);

      if (index >= 0) {
        hasBeenFound = true;

        if (changed.active === false) {
          group.eventBetTypes.splice(index, 1);
          group.eventBetTypes = group.eventBetTypes.slice();
        } else {
          updateEventBetTypeAfterPush(group.eventBetTypes[index], changed);
        }
      }
    });

    return hasBeenFound;
  }

  private handleNewEventBetType(changed: EventBetTypeChangedModel): void {
    this.eventsService
      .getEventBetType(changed.eventBetTypeId)
      .pipe(takeUntil(this.destroy$))
      .subscribe((ebt: EventBetType) => {
        const groupIndex: number = this.eventBetTypesGroupedByBetType.findIndex(
          (x: EventBetTypeGroupedByBetType) => x.betTypeId === ebt.betTypeId
        );

        if (groupIndex === -1) {
          this.insertNewGroup(ebt);
        } else {
          this.eventBetTypesGroupedByBetType[groupIndex].eventBetTypes.push(ebt);
          this.eventBetTypesGroupedByBetType[groupIndex] = {
            ...this.eventBetTypesGroupedByBetType[groupIndex]
          };
        }

        if (ebt.betTypeGroup && !this.filters.includes(BetTypeGroup[ebt.betTypeGroup])) {
          this.filters.push(BetTypeGroup[ebt.betTypeGroup]);
        }

        if (this.isNewPlayerStatsBetType(ebt)) {
          this.hasNewPlayerStatsBetType = true;
        }

        this.filter();
        this.cdRef.markForCheck();

        this.cleanupManualBetTypesIfNeeded(ebt);
      });
  }

  private insertNewGroup(ebt: EventBetType): void {
    const indexToInsert: number = this.eventBetTypeGroupingService.findInsertionIndex(
      this.eventBetTypesGroupedByBetType,
      ebt.displayPriority
    );

    const mapped: EventBetType = this.eventBetTypeGroupingService.cloneEventBetType(ebt);
    const newGroup: EventBetTypeGroupedByBetType = this.eventBetTypeGroupingService.createGroup(
      ebt,
      mapped,
      this.event
    );

    if (indexToInsert === -1) {
      this.eventBetTypesGroupedByBetType.push(newGroup);
    } else {
      this.eventBetTypesGroupedByBetType.splice(indexToInsert, 0, newGroup);
    }

    this.eventBetTypesGroupedByBetType = this.eventBetTypesGroupedByBetType.slice();
  }

  private cleanupManualBetTypesIfNeeded(ebt: EventBetType): void {
    const hasManualGroups: boolean = this.eventBetTypesGroupedByBetType.some(
      (g: EventBetTypeGroupedByBetType) => g.isManual === true
    );

    if (ebt.betTypeId > 20000 && hasManualGroups) {
      this.eventBetTypesFiltersComponent?.resetFilter(BetTypeGroup[BetTypeGroup.Result]);
      this.eventBetTypesGroupedByBetType = this.eventBetTypesGroupedByBetType.filter(
        (g: EventBetTypeGroupedByBetType) => g.isManual === false
      );
      this.cdRef.markForCheck();
    }
  }

  private subscribeToEventChanges(): void {
    this.pushService.eventChanged$.pipe(takeUntil(this.destroy$)).subscribe(changed => {
      if (this.eventId !== changed.eventId) {
        return;
      }

      this.event = updateEventAfterPush(this.event, [], changed);
      this.computeIsLive();

      if (this.isLiveEvent) {
        this.isBetBuilderToggled = false;
        this.event.allowBetBuilder = false;
      }

      if (changed.changes['liveBettingAllowed'] !== undefined || changed.changes['betStop'] !== undefined) {
        this.propagateBettingAllowed(changed.changes);
      }

      if (changed.changes['state'] === EventStateType.Finished) {
        this.eventBetTypesGroupedByBetType = [];
        this.filteredEventBetTypesGroupedByBetType = [];
        this.filters = [];
        this.filter();
      }

      this.cdRef.markForCheck();
    });
  }

  private propagateBettingAllowed(changes: Record<string, any>): void {
    const allowed: boolean =
      changes['liveBettingAllowed'] === undefined ? !changes['betStop'] : changes['liveBettingAllowed'];

    this.eventBetTypesGroupedByBetType.forEach((group: EventBetTypeGroupedByBetType) => {
      group.eventBetTypes.forEach((ebt: EventBetType) => {
        ebt.bettingAllowed = allowed;
      });
      group.eventBetTypes = [...group.eventBetTypes];
    });
  }

  @Async()
  private loadData(): void {
    this.loading = true;

    this.eventsService
      .getEventDetails<Match>(this.eventId)
      .pipe(
        takeUntil(
          merge(this.destroy$, this.route.params.pipe(skip(1)), this.i18nService.languageChanged$.pipe(skip(1)))
        ),
        finalize(() => (this.loading = false))
      )
      .subscribe({
        next: (response: EventWithEventBetTypes<Match, EventBetType>) => this.handleEventResponse(response),
        error: (error: { status: number }) => {
          if (error.status === 404) {
            this.router.navigate(['/']);
          }
        }
      });
  }

  private handleEventResponse(response: EventWithEventBetTypes<Match, EventBetType>): void {
    this.event = response;
    this.computeIsLive();
    this.redirectIfNeeded();
    this.processEventBetTypes(response.eventBetTypes);
    this.handleQueryParamBetToggle(response.eventBetTypes);
    this.filter();
    this.subscriptionSubject.next();
    this.updateSelectedItems();
    this.showLmtWidgetIfNeeded();
    this.trackPageView(response.eventBetTypes);
    if (this.event?.allowBetBuilder && this.betBuilderService.shouldDisplayBetBuilderTutorial()) {
      this.openBetBuilderTutorial();
    }
    this.cdRef.markForCheck();
  }

  private redirectIfNeeded(): void {
    const parentPaths: string[] = this.route.snapshot.parent.url.map((urlSegment: UrlSegment) => urlSegment.path);
    const isLiveRoute: boolean = parentPaths.includes('live');
    const isLiveEvent: boolean = this.event.preEventOrLive === PreEventOrLiveType.Live;

    if (isLiveEvent && !isLiveRoute) {
      this.router.navigateByUrl(`/sports/live/event/${this.eventId}`, { skipLocationChange: true });
    } else if (!isLiveEvent && isLiveRoute) {
      this.router.navigateByUrl(`/sports/event/${this.eventId}`, { skipLocationChange: true });
    }
  }

  private processEventBetTypes(eventBetTypes: EventBetType[] | undefined): void {
    if (!eventBetTypes) {
      this.eventBetTypesGroupedByBetType = [];
      this.filteredEventBetTypesGroupedByBetType = [];
      this.hasNewPlayerStatsBetType = false;
      return;
    }

    this.eventBetTypesGroupedByBetType = this.eventBetTypeGroupingService.groupEventBetTypes(eventBetTypes, this.event);
    this.filters = this.eventBetTypeGroupingService.buildFilters(this.event.entryPointId, eventBetTypes);
    this.hasNewPlayerStatsBetType = eventBetTypes.some((ebt: EventBetType) => this.isNewPlayerStatsBetType(ebt));
  }

  private handleQueryParamBetToggle(eventBetTypes: EventBetType[] | undefined): void {
    const ebtiId: string | undefined = this.route.snapshot.queryParams?.ebti;

    if (!ebtiId || !eventBetTypes) {
      return;
    }

    let targetEbti: SelectableEventBetTypeItem | undefined;
    const targetEbt: EventBetType | undefined = eventBetTypes.find(
      (ebt: EventBetType) =>
        (targetEbti = ebt.eventBetTypeItems?.find((item: SelectableEventBetTypeItem) => item.id === +ebtiId))
    );

    if (!targetEbt || !targetEbti) {
      return;
    }

    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(response => {
      const alreadyExists: boolean = response.lines.some(line => line.eventBetTypeItemId === +ebtiId);

      if (!alreadyExists) {
        this.toggleEventBetTypeItem(targetEbt, targetEbti);
      }
    });
  }

  private filter(): void {
    this.filteredEventBetTypesGroupedByBetType = this.eventBetTypeGroupingService.filterGroups(
      this.eventBetTypesGroupedByBetType,
      this.activeFilter,
      this.isBetBuilderToggled
    );

    this.enrichedGroups = this.eventBetTypeViewModelService.enrichGroups(
      this.filteredEventBetTypesGroupedByBetType,
      this.betTypeIdsUsingTeamTemplate
    );
    this.renderedGroups = this.enrichedGroups.slice(0, this.BATCH_SIZE);
    this.cdRef.markForCheck();
  }

  private patchViewModels(): void {
    this.filteredEventBetTypesGroupedByBetType = this.eventBetTypeGroupingService.filterGroups(
      this.eventBetTypesGroupedByBetType,
      this.activeFilter,
      this.isBetBuilderToggled
    );

    const result: { groups: EventBetTypeGroupView[]; changed: boolean } = this.eventBetTypeViewModelService.patchGroups(
      this.enrichedGroups,
      this.filteredEventBetTypesGroupedByBetType,
      this.betTypeIdsUsingTeamTemplate
    );

    this.enrichedGroups = result.groups;

    if (result.changed) {
      const visibleCount: number = Math.max(this.renderedGroups.length, this.BATCH_SIZE);
      this.renderedGroups = this.enrichedGroups.slice(0, Math.min(visibleCount, this.enrichedGroups.length));
    }
  }

  private updateSelectedItems(): void {
    const updatedAll: EventBetTypeGroupedByBetType[] = this.eventsMapperService.updateEventBetTypesGroupedByBetType(
      this.eventBetTypesGroupedByBetType,
      this.selectedItems,
      this.isLoadingOdds,
      this.event
    );

    if (updatedAll === this.eventBetTypesGroupedByBetType) {
      return;
    }

    this.eventBetTypesGroupedByBetType = updatedAll;

    this.betTypeIdsUsingTeamTemplate = this.eventBetTypeGroupingService.getBetTypeIdsWithHomeOrAway(
      this.eventBetTypesGroupedByBetType
    );

    this.teamGroupedItemsByBetType = this.eventsMapperService.populateRecordTeamList(
      Array.from(this.betTypeIdsUsingTeamTemplate),
      this.eventBetTypesGroupedByBetType
    );

    this.patchViewModels();
    this.cdRef.markForCheck();
  }

  private trackPageView(eventBetTypes: EventBetType[]): void {
    const odds: Record<string, string> | null = this.extractOdds(eventBetTypes);

    if (!odds) {
      return;
    }

    this.telemetryService.trackEvent('event_view', {
      matchId: this.event.id,
      homeTeamName: this.event.homeTeamName,
      awayTeamName: this.event.awayTeamName,
      expectedStart: this.event.expectedStart.toISOString(),
      tournament: this.event.categories?.[0] ?? '',
      sport: getNameForEntryPoint(this.event.entryPointId),
      language: this.i18nService.currentLanguageCode,
      ...odds
    });
  }

  private extractOdds(eventBetTypes: EventBetType[]): Record<string, string> | null {
    const threeWay: EventBetType | undefined = this.findBetType(
      eventBetTypes,
      EventWithEventBetTypesComponent.THREE_WAY_BET_IDS
    );
    const twoWay: EventBetType | undefined = this.findBetType(
      eventBetTypes,
      EventWithEventBetTypesComponent.TWO_WAY_BET_IDS
    );

    if (threeWay?.eventBetTypeItems?.length) {
      const [home, draw, away]: SelectableEventBetTypeItem[] = threeWay.eventBetTypeItems;
      const result: Record<string, string> = {
        homeTeamOdds: this.getActiveOdds(home),
        drawOdds: this.getActiveOdds(draw),
        awayTeamOdds: this.getActiveOdds(away)
      };

      if (Object.values(result).some(Boolean)) {
        return result;
      }
    }

    if (twoWay?.eventBetTypeItems?.length) {
      const [home, away]: SelectableEventBetTypeItem[] = twoWay.eventBetTypeItems;
      const result: Record<string, string> = {
        homeTeamOdds: this.getActiveOdds(home),
        drawOdds: '',
        awayTeamOdds: this.getActiveOdds(away)
      };

      if (Object.values(result).some(Boolean)) {
        return result;
      }
    }

    return null;
  }

  private isNewPlayerStatsBetType(ebt: EventBetType): boolean {
    return (
      ebt.betTypeId === EventWithEventBetTypesComponent.NEW_PLAYER_STATS_BET_TYPE_ID &&
      !!ebt.betTypeGroup &&
      hasFlag(ebt.betTypeGroup, BetTypeGroup.PlayerStats)
    );
  }

  private findBetType(eventBetTypes: EventBetType[], betTypeIds: number[]): EventBetType | undefined {
    return eventBetTypes?.find((ebt: EventBetType) => betTypeIds.includes(ebt.betTypeId));
  }

  private getActiveOdds(item: SelectableEventBetTypeItem): string {
    return item.active && item.bettingAllowed ? item.odds.toString() : '';
  }

  private showLmtWidgetIfNeeded(): void {
    if (this.isLiveEvent && this.lmtAllowedEntryPoints.includes(this.event.entryPointId)) {
      this.bcService.broadcast('LMT.Widget.Show', { sourceRef: this.event.sourceRef });
    }
  }

  private applyStickyState(media: Media): void {
    const params: StickyHeaderParams = {
      yOffset: window.pageYOffset,
      media,
      countMessages: this.countMessages ?? 0,
      eventBetGroupsHeight: this.eventBetGroupsHeight,
      scoreWidgetHeight: this.scoreWidgetInitalHeight ?? 0,
      blockEventHeight: this.blockEventHeight ?? 0,
      isLiveEvent: this.isLiveEvent,
      hasStatsDisplayed: this.hasStatsDisplayed,
      hostBottomDistance: this.hostRef.nativeElement.getBoundingClientRect().bottom - window.innerHeight
    };

    const state: {
      isStickyHeader: boolean;
      isStickyFilters: boolean;
      blockEventMobileHeight: number;
      shouldCaptureScoreWidgetHeight: boolean;
    } = this.eventPageStickyHeaderService.computeStickyState(params);

    this.isStickyHeader = state.isStickyHeader;
    this.isStickyFilters = state.isStickyFilters;
    this.blockEventMobileHeight = state.blockEventMobileHeight;

    if (state.shouldCaptureScoreWidgetHeight && this.scoreWidgetElement?.nativeElement) {
      this.setScoreWidgetHeight();
    }

    this.cdRef.markForCheck();
  }

  private processElementHeights(elements: QueryList<ElementRef>): void {
    if (!elements?.length) {
      return;
    }

    this.eventBetGroupsHeight = elements.reduce((total: number, child: ElementRef) => {
      const height: number = child?.nativeElement?.offsetHeight;
      return height == null ? total : total + Math.min(height, this.COLLAPSE_THRESHOLD);
    }, 0);

    this.cdRef.detectChanges();
  }

  private computeIsLive(): void {
    this.isLiveEvent =
      !!this.event &&
      this.event.state !== EventStateType.Undisputed &&
      this.event.state !== EventStateType.Unknown &&
      this.event.state !== EventStateType.Finished &&
      this.event.state !== EventStateType.Settled &&
      this.event.state !== EventStateType.AboutToStart;
  }

  private isLiveWithFixedHeader(): boolean {
    return this.isLiveEvent && this.fixedSportEventHeader;
  }

  private listenOnLoadingOddsChanges(): void {
    this.betSlipBetLinesService.isLoadingOddsEventIds$
      .pipe(takeUntil(this.destroy$))
      .subscribe((isLoadingOdds: number[]) => {
        this.isLoadingOdds = !!isLoadingOdds.length;
        this.updateSelectedItems();
        this.cdRef.markForCheck();
      });
  }
}
