import { ViewportScroller } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit, Optional } from '@angular/core';
import { ActivatedRoute, Params, Router } from '@angular/router';
import { merge } from 'rxjs';
import { finalize, skip, takeUntil } from 'rxjs/operators';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { DestroySubject, kioskToken, Scope, scopeToken } from '@honoregaming/core';
import {
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  SmarticoService,
  TelemetryService
} from '@honoregaming/customer-core';
import { EventCategoriesService, EventsService } from '@honoregaming/events';
import { I18nService } from '@honoregaming/i18n';
import {
  BetCategoryType,
  EventCategory,
  EventTab,
  EventTabTypes,
  EventWithEventBetTypes,
  Match,
  OddsBoostType
} from '@honoregaming/types';
import { Media, MediaService } from '@honoregaming/ui';

@Component({
  selector: 'hg-sports-ordered-home',
  templateUrl: './sports-ordered-home.component.html',
  styleUrls: ['./sports-ordered-home.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsOrderedHomeComponent extends DestroySubject implements OnInit {
  BetCategoryType = BetCategoryType;
  isLoading: boolean = false;
  isHomePage: boolean = true;
  topWinBetsActivated: boolean = false;
  sportFiltersAnchor: string = 'sport-filters-links';
  activeEntryPoint?: number;
  links: any;
  entryPoints: EventCategory[] = [];
  Scope = Scope;

  hasOddsBoostFeature: boolean = this.operatorConfiguration.operatorFeatures.includes('OddsBoost');
  hasManualOddsFeature: boolean = this.operatorConfiguration.operatorFeatures.includes('ManualOdds');
  hasOddsBoosts: boolean = false;
  hasManualOdds: boolean = false;
  hasCustomOddsTabOnHomeActive?: boolean;
  internalSelectedCustomOddsTab?: OddsBoostType;

  params?: Params;

  EventTabTypes = EventTabTypes;
  eventTabsList?: EventTab[];
  currentTab: EventTab = { type: EventTabTypes.Upcoming };
  lastEventTabType?: EventTabTypes;
  firstEventTabType?: EventTabTypes;
  currentLanguage: string = this.i18nService.currentLanguageCode;
  elementsOrder?: string[];
  displayTopWins: boolean = false;
  displayMissionsBanner: boolean = false;

  constructor(
    private readonly i18nService: I18nService,
    private readonly eventCategoriesService: EventCategoriesService,
    private readonly router: Router,
    private readonly viewportScroller: ViewportScroller,
    private readonly cdRef: ChangeDetectorRef,
    private readonly eventsService: EventsService,
    private readonly activatedRoute: ActivatedRoute,
    private readonly telemetryService: TelemetryService,
    private readonly smarticoService: SmarticoService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    @Inject(kioskToken) public readonly isKiosk: boolean,
    @Inject(scopeToken) public readonly scope: Scope,
    @Inject(customerOperatorConfigurationToken)
    private readonly customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Optional() private readonly mediaService: MediaService
  ) {
    super();
  }

  ngOnInit(): void {
    this.initConfiguration();
    this.checkTabAvailability();
    this.loadOddsBoosts();
    this.loadEntryPoints();
    this.subscribeToTopWinBetsVisibility();
    this.subscribeToLanguageChanges();
    this.initElementsOrder();
  }

  trackByFn(_index, item: EventWithEventBetTypes<Match>): number {
    return item.id;
  }

  clickOnEntryPoint(id: number): void {
    this.activeEntryPoint = id;
  }

  setTab(tab: EventTab): void {
    const [x, y] = this.viewportScroller.getScrollPosition();
    this.currentTab = tab;
    this.router
      .navigate([], {
        queryParams: {
          ...this.params,
          tab: this.currentTab.type
        }
      })
      .then(() => {
        this.viewportScroller.scrollToPosition([x, y]);
      });
  }

  clickOnTab(eventTab: EventTab, index: number): void {
    this.telemetryService.trackEvent('sportbar_click', {
      tab_name: eventTab.type,
      tab_label: this.i18nService.translateSync(eventTab.text),
      tab_position: index
    });
  }

  private initConfiguration(): void {
    const { onlineConfiguration } = this.operatorConfiguration;

    this.hasCustomOddsTabOnHomeActive = onlineConfiguration?.displayCustomOddsTabOnHome;
    this.internalSelectedCustomOddsTab = onlineConfiguration?.customOddsTypeTabOnHome;
    this.isHomePage = !this.customerOperatorConfiguration.onlineConfiguration?.homePageCasino;
  }

  private loadOddsBoosts(): void {
    if (this.hasManualOddsFeature) {
      this.getManualOddsBoosts();
    }

    if (this.hasOddsBoostFeature) {
      this.getOddsBoosts();
    }
  }

  private subscribeToLanguageChanges(): void {
    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(language => {
      this.currentLanguage = language;
      const previousActiveEntryPoint = this.activeEntryPoint;
      this.loadEntryPoints();
      this.activeEntryPoint = previousActiveEntryPoint;
      this.cdRef.markForCheck();
    });
  }

  private initElementsOrder(): void {
    const homePageCustomization =
      this.customerOperatorConfiguration.customization['homepage'] ??
      this.customerOperatorConfiguration.customization['sports-homepage'];

    if (!homePageCustomization?.elementsOrder) {
      return;
    }

    const { elementsOrder } = homePageCustomization;
    const { topWinBetsConfiguration } = this.operatorConfiguration;

    this.elementsOrder = elementsOrder[this.mediaService.media >= Media.lg ? 'desktop' : 'mobile'];

    this.displayTopWins =
      elementsOrder.mobile?.includes('top-wins') &&
      (topWinBetsConfiguration.displayOnline || topWinBetsConfiguration.displayRetail);

    this.displayMissionsBanner = this.smarticoService.isEnabled && elementsOrder.mobile?.includes('missions-banner');
  }

  private checkTabAvailability(): void {
    const { customization } = this.customerOperatorConfiguration;
    const config = customization['homepage'] ?? customization['sports-homepage'];

    this.eventTabsList = config?.eventTabs.filter(tab => this.isTabEnabled(tab.type)) ?? [];

    this.handleQueryParams();
  }

  private isTabEnabled(type: EventTabTypes): boolean {
    switch (type) {
      case EventTabTypes.Live:
      case EventTabTypes.Upcoming:
        return true;

      case EventTabTypes.OddsBoost:
        return (
          !this.isKiosk &&
          this.hasCustomOddsTabOnHomeActive &&
          this.internalSelectedCustomOddsTab === OddsBoostType.Automatic &&
          this.hasOddsBoostFeature &&
          this.hasOddsBoosts
        );

      case EventTabTypes.ManualOdds:
        return (
          !this.isKiosk &&
          this.hasCustomOddsTabOnHomeActive &&
          this.internalSelectedCustomOddsTab === OddsBoostType.Manual &&
          this.hasManualOddsFeature &&
          this.hasManualOdds
        );

      default:
        return false;
    }
  }

  private getManualOddsBoosts(): void {
    this.eventsService
      .getManualOddsBoosts()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(manualOddsBoosts => {
        if (manualOddsBoosts?.result?.length ?? 0 > 0) {
          this.hasManualOdds = true;
          this.checkTabAvailability();
        }
      });
  }

  private getOddsBoosts(): void {
    this.eventsService
      .getOddsBoosts(this.currentLanguage)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(oddsBoosts => {
        if (oddsBoosts?.length) {
          this.hasOddsBoosts = true;
          this.checkTabAvailability();
        }
      });
  }

  private handleQueryParams(): void {
    this.activatedRoute.queryParams.pipe(takeUntil(this.destroy$)).subscribe(params => {
      this.params = params;
      const tabType = params['tab'] || EventTabTypes.Upcoming;
      this.currentTab = this.eventTabsList.find(tab => tab.type === tabType) ?? this.eventTabsList[0];
      this.cdRef.markForCheck();
    });
  }

  private loadEntryPoints(): void {
    const customization = this.customerOperatorConfiguration.customization[this.sportFiltersAnchor];

    if (customization) {
      this.links = customization.map(item => Number(item.entryPointId));
      this.activeEntryPoint = this.links[0];
    }

    this.eventCategoriesService
      .getEntryPoints()
      .pipe(takeUntil(merge(this.destroy$, this.i18nService.languageChanged$.pipe(skip(1)))))
      .subscribe(entryPoints => {
        this.entryPoints = entryPoints.filter(entryPoint => this.links.includes(Number(entryPoint.id)));
        this.cdRef.markForCheck();
      });
  }

  private subscribeToTopWinBetsVisibility(): void {
    const { operatorFeatures, topWinBetsConfiguration } = this.operatorConfiguration;

    if (!operatorFeatures.includes('TopWinBets')) {
      return;
    }

    const hasDisplayMode: boolean = topWinBetsConfiguration.displayOnline || topWinBetsConfiguration.displayRetail;

    if (!hasDisplayMode) {
      return;
    }

    this.mediaService?.media$.pipe(takeUntil(this.destroy$)).subscribe(media => {
      this.topWinBetsActivated = media < Media.lg;
      this.cdRef.markForCheck();
    });
  }
}
