import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject, OnDestroy } from '@angular/core';
import {
  Async,
  AsyncTrigger,
  DestroySubject,
  updateEventBetTypeAfterPush,
  PushService,
  updateEventAfterPush,
  kioskToken,
  CompleteMyBetService,
  ApplicationEvent,
  BroadcastingService
} from '@honoregaming/core';
import { finalize, takeUntil } from 'rxjs/operators';
import { Subscription } from 'rxjs';
import {
  BetCategoryType,
  EventBetType,
  EventBetTypeItem,
  EventStateType,
  Match,
  SelectableEventBetTypeItem,
  SelectedItem,
  TopCombo
} from '@honoregaming/types';
import { BetLine, BetSlipService, createBetLine } from '@honoregaming/betslip';
import { I18nService } from '@honoregaming/i18n';
import { EventsService } from '@honoregaming/events';
import { TelemetryService } from '@honoregaming/customer-core';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';

@Component({
  selector: 'hg-top-combos',
  templateUrl: './top-combos.component.html',
  styleUrls: ['./top-combos.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TopCombosComponent extends DestroySubject implements OnInit, OnDestroy {
  private static readonly ITEMS_PER_PAGE = 4;
  private static readonly SCROLL_DELAY = 50;

  private eventBetTypesPushSubscription?: Subscription;
  private eventsPushSubscription?: Subscription;

  isLoadingTopCombos?: boolean;
  selectedItems: SelectedItem[] = [];
  private activeTopComboKey?: string;

  topCombos: (TopCombo & { totalEventBetTypeItem: EventBetTypeItem })[] = [];
  currentPage: { [key: number]: number } = {};
  canScrollLeft? = false;
  canScrollRight? = false;

  constructor(
    private readonly cdRef: ChangeDetectorRef,
    private readonly betSlipService: BetSlipService,
    private readonly eventsService: EventsService,
    private readonly i18nService: I18nService,
    protected readonly pushService: PushService,
    private readonly completeMyBetService: CompleteMyBetService,
    private readonly telemetryService: TelemetryService,
    private readonly bcService: BroadcastingService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    @Inject(kioskToken) public readonly isKiosk: boolean
  ) {
    super();
  }

  @AsyncTrigger() languageTrigger = this.i18nService.languageChanged$;

  ngOnInit(): void {
    this.getTopCombos();

    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(event => {
      this.selectedItems = event.lines.map(se => ({
        eventId: se.eventId!,
        betTypeId: se.betTypeId!,
        eventBetTypeItemId: se.eventBetTypeItemId!,
        isBetCompletion: se.isBetCompletion!
      }));

      this.topCombos?.forEach(tc => {
        tc.selected = this.isTopComboSelected(tc);
      });

      this.cdRef.markForCheck();
    });

    this.cdRef.markForCheck();
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();

    this.eventBetTypesPushSubscription?.unsubscribe();
    this.eventsPushSubscription?.unsubscribe();

    this.pushService.subscribeToEvents([]);
    this.pushService.subscribeToOdds([], []);
  }

  public onHorizontalScroll(): void {
    this.updateHorizontalScrollState();
  }

  public scrollCardsLeft(): void {
    const container: HTMLElement | null = document.querySelector('.main-container');
    if (container) {
      container.scrollBy({ left: -this.getCardScrollWidth(container), behavior: 'smooth' });
    }
  }

  public scrollCardsRight(): void {
    const container: HTMLElement | null = document.querySelector('.main-container');
    if (container) {
      container.scrollBy({ left: this.getCardScrollWidth(container), behavior: 'smooth' });
    }
  }

  public isAtFirstPage(index: number): boolean {
    return this.currentPage[index] > 0;
  }

  public isAtLastPage(index: number): boolean {
    const combo: TopCombo & {
      totalEventBetTypeItem: EventBetTypeItem;
    } = this.topCombos[index];
    if (!combo || combo.lines.length <= TopCombosComponent.ITEMS_PER_PAGE) {
      return false;
    }
    const totalPages: number = Math.ceil(combo.lines.length / TopCombosComponent.ITEMS_PER_PAGE) - 1;
    return (this.currentPage[index] || 0) >= totalPages;
  }

  public isFourthVisibleMatch(comboIndex: number, lineIndex: number): boolean {
    const currentPage: number = this.currentPage[comboIndex] || 0;
    return lineIndex === (currentPage + 1) * TopCombosComponent.ITEMS_PER_PAGE - 1;
  }

  public isTopComboCompletionDisabled(match: Match, item: SelectableEventBetTypeItem): boolean {
    return this.completeMyBetService.isTopMatchCompletionDisabled(this.selectedItems, match, item);
  }

  public toggleExpandCombo(index: number, direction: 'up' | 'down' = 'down'): void {
    const combo: TopCombo & {
      totalEventBetTypeItem: EventBetTypeItem;
    } = this.topCombos[index];
    if (!combo || combo.lines.length <= TopCombosComponent.ITEMS_PER_PAGE) {
      return;
    }

    // Initialize current page if not set
    if (this.currentPage[index] === undefined) {
      this.currentPage[index] = 0;
    }

    const totalPages: number = Math.ceil(combo.lines.length / TopCombosComponent.ITEMS_PER_PAGE) - 1;

    // Calculate next page but don't update yet
    let nextPage: number = this.currentPage[index];
    if (direction === 'down') {
      if (nextPage < totalPages) {
        nextPage++;
      }
    } else {
      if (nextPage > 0) {
        nextPage--;
      }
    }

    // Only proceed if page actually changed
    if (nextPage !== this.currentPage[index]) {
      // Scroll to the appropriate position, then update the page
      this.scrollToPage(index, nextPage);
    }
  }

  public addBetToBetSlip(topCombo: TopCombo): void {
    const topComboKey: string = this.getTopComboKey(topCombo);

    if (topCombo.selected) {
      this.activeTopComboKey = undefined;

      topCombo.lines.forEach(line => {
        const item: SelectableEventBetTypeItem = line.eventBetType.eventBetTypeItems[0];
        if (this.isSelectedItem(item.id)) {
          this.toggleBet(null, line.event, line.eventBetType, item);
        }
      });
    } else {
      this.activeTopComboKey = topComboKey;

      if (!this.operatorConfiguration.topCombosConfiguration?.additionMode) {
        this.betSlipService.clear();
      }

      topCombo.lines.forEach(line => {
        const item: SelectableEventBetTypeItem = line.eventBetType.eventBetTypeItems[0];
        if (!this.isSelectedItem(item.id)) {
          this.toggleBet(null, line.event, line.eventBetType, item);
        }
      });
    }

    this.topCombos?.forEach(tc => {
      tc.selected = this.isTopComboSelected(tc);
    });

    this.telemetryService.trackEvent('top_combo_click_on_full_bet');

    this.cdRef.markForCheck();
  }

  private toggleBet(
    event: Event | null,
    selectedEvent: Match,
    ebt: EventBetType,
    item: SelectableEventBetTypeItem
  ): void {
    if (event) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }

    if (
      item.odds! <= 1 ||
      !ebt.active ||
      !ebt.bettingAllowed ||
      !item.active ||
      !item.bettingAllowed ||
      this.isTopComboCompletionDisabled(selectedEvent, item)
    ) {
      return;
    }

    const wasSelected: boolean = this.isSelectedItem(item.id);
    const betLine: BetLine = createBetLine(selectedEvent, ebt, item, BetCategoryType.SportsFixedOdds);

    if (wasSelected) {
      this.betSlipService.removeBetLine(betLine);
    } else {
      this.bcService.broadcast(ApplicationEvent.BetSelected, {
        event: { ...selectedEvent, expectedStart: new Date(selectedEvent.expectedStart) },
        eventBetType: ebt
      });
      this.betSlipService.addBetLine(betLine);
    }

    this.cdRef.markForCheck();
  }

  private isTopComboFullySelected(topCombo: TopCombo): boolean {
    return topCombo.lines.every(
      line => !!this.selectedItems.some(item => item.eventBetTypeItemId === line.eventBetType.eventBetTypeItems[0].id)
    );
  }

  private isTopComboSelected(topCombo: TopCombo): boolean {
    if (!this.activeTopComboKey) {
      return false;
    }

    return this.activeTopComboKey === this.getTopComboKey(topCombo) && this.isTopComboFullySelected(topCombo);
  }

  private getTopComboKey(topCombo: TopCombo): string {
    return topCombo.lines
      .map(line => line.eventBetType.eventBetTypeItems[0].id)
      .sort((a, b) => a - b)
      .join('|');
  }

  @Async()
  private getTopCombos(): void {
    this.isLoadingTopCombos = true;
    this.eventsService
      .getTopCombos()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoadingTopCombos = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(results => {
        this.topCombos = results.map(tc => ({
          ...tc,
          totalEventBetTypeItem: this.createTotalEventBetTypeItem(tc.totalOdds)
        }));

        this.topCombos?.forEach(tc => {
          tc.selected = this.isTopComboSelected(tc);
        });

        this.subscribeToPushChanges();
        this.registerToPushChanges();

        this.cdRef.markForCheck();

        setTimeout(() => this.updateHorizontalScrollState(), TopCombosComponent.SCROLL_DELAY);
      });
  }

  private subscribeToPushChanges(): void {
    if (!this.eventBetTypesPushSubscription) {
      this.eventBetTypesPushSubscription = this.pushService.eventBetTypeChanged$
        .pipe(takeUntil(this.destroy$))
        .subscribe(changed => {
          this.topCombos.forEach(tc => {
            tc.lines.forEach(line => {
              const isSame: boolean = line.eventBetType.id === changed.eventBetTypeId;
              if (isSame) {
                if (changed.active === false) {
                  line.eventBetType.bettingAllowed = false; // HACK until better solution
                } else {
                  updateEventBetTypeAfterPush(line.eventBetType, changed);
                }

                line.eventBetType = { ...line.eventBetType };
                this.cdRef.markForCheck();
              }
            });

            tc.totalEventBetTypeItem = {
              ...tc.totalEventBetTypeItem,
              odds: this.calculateTotalOdds(tc.lines)
            };
          });
        });
    }

    if (!this.eventsPushSubscription) {
      this.eventsPushSubscription = this.pushService.eventChanged$.pipe(takeUntil(this.destroy$)).subscribe(changed => {
        let eventChangedToLiveState: boolean = false;

        this.topCombos.forEach(tc => {
          tc.lines.forEach(line => {
            if (line.event.id === changed.eventId) {
              tc = updateEventAfterPush(line.event, [line.eventBetType], changed);
              if (
                changed.changes['state'] &&
                changed.changes['state'] !== EventStateType.AboutToStart &&
                changed.changes['state'] !== EventStateType.Undisputed &&
                changed.changes['state'] !== EventStateType.Delayed
              ) {
                eventChangedToLiveState = true;
              }

              this.cdRef.markForCheck();
            }
          });
        });

        if (eventChangedToLiveState) {
          this.onEventChangedToLiveState();
        }
      });
    }
  }

  private onEventChangedToLiveState(): void {
    this.getTopCombos();
  }

  private registerToPushChanges(): void {
    const eventIds: Array<number> = this.topCombos?.length
      ? this.topCombos.map(combo => combo.lines.map(line => line.event.id)).reduce((a, b) => a.concat(b), [])
      : [];
    const betTypeIds: Array<number> = this.topCombos?.length
      ? this.topCombos.map(combo => combo.lines.map(line => line.eventBetType.id)).reduce((a, b) => a.concat(b), [])
      : [];

    this.pushService.subscribeToEvents(eventIds, 'topCombos');
    this.pushService.subscribeToOdds(betTypeIds, [], 'topCombos');
  }

  private isSelectedItem(eventBetTypeItemId: number): boolean {
    return !!this.selectedItems.find((item: SelectedItem) => item.eventBetTypeItemId === eventBetTypeItemId);
  }

  private updateHorizontalScrollState(): void {
    const container: HTMLElement | null = document.querySelector('.main-container');
    if (container) {
      this.canScrollLeft = container.scrollLeft > 0;
      this.canScrollRight =
        container.scrollLeft + container.clientWidth < container.scrollWidth - 1 && this.topCombos?.length > 3;
      this.cdRef.markForCheck();
    }
  }

  private getCardScrollWidth(container: HTMLElement): number {
    const card: HTMLElement | null = container.querySelector('.top-combo');
    const gap: number = 8;
    return card ? card.offsetWidth + gap : 616;
  }

  private scrollToPage(index: number, targetPage: number): void {
    setTimeout(() => {
      const comboElements: NodeListOf<Element> = document.querySelectorAll('.top-combo__matches');
      const comboElement: HTMLElement = comboElements[index] as HTMLElement;
      if (comboElement) {
        const pageHeight: number = this.calculatePageHeight(comboElement);
        if (pageHeight > 0) {
          const scrollPosition: number = targetPage * pageHeight;

          comboElement.scrollTo({
            top: scrollPosition,
            behavior: 'smooth'
          });

          // Update arrow visibility midway through the scroll animation
          this.currentPage[index] = targetPage;
          this.cdRef.markForCheck();
        }
      }
    }, TopCombosComponent.SCROLL_DELAY);
  }

  private calculatePageHeight(container: HTMLElement): number {
    const matchElements: NodeListOf<Element> = container.querySelectorAll('.top-combo__match');
    if (matchElements.length < TopCombosComponent.ITEMS_PER_PAGE) {
      return 0;
    }

    let totalHeight: number = 0;
    for (let i = 0; i < TopCombosComponent.ITEMS_PER_PAGE; i++) {
      totalHeight += (matchElements[i] as HTMLElement).offsetHeight;
    }
    return totalHeight;
  }

  private createTotalEventBetTypeItem(odds: number): EventBetTypeItem {
    return {
      id: 0,
      betTypeItemId: 0,
      shortName: '',
      bettingAllowed: false,
      active: false,
      odds
    };
  }

  private calculateTotalOdds(lines: Array<{ eventBetType: EventBetType }>): number {
    return lines.reduce((sum, line) => sum * line.eventBetType.eventBetTypeItems[0].odds!, 1);
  }
}
