import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  OnInit,
  EventEmitter,
  Output,
  Optional,
  Input,
  SimpleChanges,
  Inject,
  OnChanges,
  NgZone
} from '@angular/core';
import { ActivatedRoute, Params, Router } from '@angular/router';
import { PreEventOrLiveType, Match, EventCategory, OpenCloseState, EventWithEventBetTypes } from '@honoregaming/types';
import {
  ApplicationEvent,
  Async,
  BroadcastingService,
  PushService,
  kioskToken,
  BetLinesMapperService
} from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { finalize, skip, switchMap, take, takeUntil } from 'rxjs/operators';
import { BetType, EventBetType } from '@honoregaming/types';
import { BetSlipBetLinesService, BetSlipService } from '@honoregaming/betslip';
import {
  EventCategoriesService,
  EventsService,
  FetchEventBetTypesMode,
  EventsMapperService
} from '@honoregaming/events';
import { EventsWithEventBetTypesComponentBase } from '@honoregaming/sports-ui';
import { merge, Subject, Subscription } from 'rxjs';
import { Media, MediaService } from '@honoregaming/ui';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';

@Component({
  selector: 'hg-events-by-event-category',
  templateUrl: './events-by-event-category.container.html',
  styleUrls: ['./events-by-event-category.container.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventsByEventCategoryComponent extends EventsWithEventBetTypesComponentBase implements OnInit, OnChanges {
  @Input() sportId: number;
  @Input() isInHomePage: boolean = false;
  @Input() topWinBetsActivated: boolean;
  @Input() orderByPopularEvents: boolean = false;

  betTypesNumberToDisplay?: number;
  rootCategoryId: number;
  categoryId: number;

  selectedBetType: BetType;

  loading = false;
  oddsFilterActive = false;
  eventCategoriesFilterActive = false;

  betTypes: BetType[];
  page = 0;
  hasMore: boolean;
  oddsFilter: number;

  eventCategoriesFilter: EventCategory[];
  eventCategoriesIds: number[];
  eventCategoriesSelectionCount: number;
  eventCategoriesNames: string[];

  filterChanged$ = new Subject();

  eventCategories: EventCategory[];
  @Output()
  close = new EventEmitter<void>();
  @Output()
  navigated = new EventEmitter<void>();
  params: Params;

  entryPoints: {
    root: EventCategory;
    eventCategories: EventCategory[];
    loadingEventCategories: boolean;
  }[];
  currentEntryPoint: {
    root: EventCategory;
    eventCategories: EventCategory[];
    topCategories?: EventCategory[];
    loadingEventCategories: boolean;
  };

  loadingMore: boolean = false;
  isChangingFilters: boolean = false;
  displayTopWins: boolean = true;

  constructor(
    private eventCategoriesService: EventCategoriesService,
    private route: ActivatedRoute,
    private eventsService: EventsService,
    private router: Router,
    private readonly zone: NgZone,
    protected i18nService: I18nService,
    protected betSlipService: BetSlipService,
    protected pushService: PushService,
    protected cdRef: ChangeDetectorRef,
    protected bcService: BroadcastingService,
    protected eventsMapperService: EventsMapperService,
    protected betLinesMapperService: BetLinesMapperService,
    protected betSlipBetLinesService: BetSlipBetLinesService,
    @Inject(kioskToken) public isKiosk: boolean,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Optional() private mediaService: MediaService
  ) {
    super(
      i18nService,
      betSlipService,
      pushService,
      cdRef,
      bcService,
      eventsMapperService,
      betLinesMapperService,
      betSlipBetLinesService
    );
  }

  queryParamsSubscription: Subscription;

  ngOnInit() {
    super.ngOnInit();
    if (!this.isInHomePage) {
      this.route.params.subscribe(params => {
        if (
          this.sportId !== +params['sport'] ||
          this.categoryId !== +params['category'] ||
          this.rootCategoryId !== +params['rootCategory'] ||
          params['sport'] === undefined
        ) {
          if (!isNaN(params['sport']) && this.sportId !== +params['sport']) {
            this.sportId = +params['sport'];
            this.betTypes = null;
            this.selectedBetType = null;
          }

          this.categoryId = params['category'] ? +params['category'] : null;
          this.rootCategoryId = params['rootCategory'] ? +params['rootCategory'] : null;

          if (this.queryParamsSubscription) {
            this.queryParamsSubscription.unsubscribe();
          }

          this.queryParamsSubscription = this.route.queryParams.subscribe(params => {
            this.params = params;
            const eventCategoriesIds: string[] = params['eventCategoriesIds']?.split(',');
            if (eventCategoriesIds?.length > 0) {
              this.eventCategoriesIds = eventCategoriesIds.map(Number);
              this.eventCategoriesSelectionCount = this.eventCategoriesIds.length;
              this.eventCategoriesFilterActive = true;
              this.eventCategoriesFilter = this.eventCategories?.filter(x => this.eventCategoriesIds.includes(x.id));
            } else {
              if (this.categoryId || this.rootCategoryId) {
                this.eventCategoriesIds = [this.categoryId ?? this.rootCategoryId];
                this.eventCategoriesSelectionCount = 1;
                this.isChangingFilters = false;
              } else {
                this.eventCategoriesIds = [];
              }
            }

            if (!isNaN(Number(params['oddsFilter']))) {
              this.oddsFilter = Number(params.oddsFilter);
              this.oddsFilterActive = !this.oddsFilterActive;
              this.closeFilters();
            } else {
              this.oddsFilter = null;
              this.oddsFilterActive = !this.oddsFilterActive;
              this.closeFilters();
            }

            if (!isNaN(Number(params['betType']))) {
              if (!this.isChangingFilters) {
                this.loadBetTypes(Number(params['betType']));
                this.isChangingFilters = false;
              }

              this.closeFilters();
            } else {
              this.selectedBetType = null;
              if (!this.isChangingFilters) {
                this.loadBetTypes();
                this.isChangingFilters = false;
              }
              this.closeFilters();
            }
          });

          this.loadBetTypes();
          this.loadEventCategories();
        }
      });
    }

    const homePageCustomization =
      this.customerOperatorConfiguration.customization['homepage'] ??
      this.customerOperatorConfiguration.customization['sports-homepage'];
    if (homePageCustomization?.elementsOrder) {
      this.displayTopWins = homePageCustomization.elementsOrder.mobile?.indexOf('top-wins') === -1;
    }
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['sportId'] && changes['sportId'].previousValue !== changes['sportId'].currentValue) {
      this.loading = true;
      this.oddsFilter = null;
      this.selectedBetType = null;
      this.loadBetTypes();
    }
  }

  @Async()
  private loadBetTypes(paramId?: number) {
    this.eventCategoriesService
      .getEntryPoints()
      .pipe(
        takeUntil(merge(this.destroy$, this.route.params.pipe(skip(1)))),
        switchMap(eventCategories => {
          const eventCategory = eventCategories.find(ec => ec.id);
          if (eventCategory) {
            this.betTypesNumberToDisplay = eventCategory.betTypesNumberToDisplay;
          }

          return this.eventCategoriesService
            .getEventCategoryBetTypes(this.sportId, this.betTypesNumberToDisplay || 4, PreEventOrLiveType.PreEvent)
            .pipe(takeUntil(merge(this.destroy$)));
        })
      )
      .subscribe(betTypes => {
        this.betTypes = betTypes;

        if (paramId && this.betTypes?.findIndex(x => x.id === paramId) > -1) {
          this.onBetTypeSelected(
            this.betTypes?.find(x => x.id === paramId),
            false
          );
        }

        if ((!this.selectedBetType || this.betTypes.indexOf(this.selectedBetType) === -1) && this.betTypes.length > 0) {
          this.onBetTypeSelected(betTypes[0], false);
        }

        this.cdRef.markForCheck();
      });
  }

  @Async()
  loadEventCategories() {
    this.eventCategoriesService
      .getEventCategories(
        this.sportId,
        ...(this.categoryId ? [this.rootCategoryId, this.categoryId] : [this.rootCategoryId])
      )
      .subscribe(eventCategories => {
        this.eventCategoriesFilter = [eventCategories[eventCategories.length - 1]];
        this.eventCategoriesNames = eventCategories.map(ec => ec.name);
        this.eventCategories = eventCategories;

        this.cdRef.markForCheck();
      });
  }

  private reloadEvents() {
    this.page = 0;
    this.events = [];
    this.filterChanged$.next();
    this.loadOrderedEvents();
  }

  private updateLoadingState(loading: boolean, showMore?: boolean) {
    if (showMore) {
      this.loadingMore = loading;
    } else {
      this.loading = loading;
    }
  }

  loadOrderedEvents(showMore?: boolean) {
    this.updateLoadingState(true, showMore);
    if (this.orderByPopularEvents) {
      this.loadPopularEvents(showMore);
    } else {
      this.loadEvents(showMore);
    }
  }

  onEventChangedToLiveState() {
    this.reloadEvents();
  }

  toggleOddsFilter() {
    this.oddsFilterActive = !this.oddsFilterActive;

    if (this.mediaService.media <= Media.md) {
      this.bcService.broadcast<OpenCloseState>(
        ApplicationEvent.OverlayStateChange,
        !!this.oddsFilterActive ? 'open' : 'close'
      );
    }
  }

  toggleEventCategoriesFilter() {
    this.eventCategoriesFilterActive = !this.eventCategoriesFilterActive;
    this.bcService.broadcast<OpenCloseState>(
      ApplicationEvent.OverlayStateChange,
      !!this.eventCategoriesFilterActive ? 'open' : 'close'
    );

    if (!this.eventCategoriesFilterActive) {
      this.eventCategoriesSelectionCount = this.eventCategoriesIds.length;
    }
  }

  closeFilters() {
    this.oddsFilterActive = false;
    this.eventCategoriesFilterActive = false;
    this.eventCategoriesSelectionCount = this.eventCategoriesIds?.length ?? 0;
    this.bcService.broadcast<OpenCloseState>(ApplicationEvent.OverlayStateChange, 'close');
  }

  setFiltersOnNavigation() {
    this.router.navigate([], {
      queryParams: {
        ...this.params,
        betType: this.selectedBetType?.id,
        oddsFilter: this.oddsFilter,
        eventCategoriesIds:
          this.eventCategoriesIds && this.eventCategoriesIds.join(',')?.length > 0
            ? this.eventCategoriesIds.join(',')
            : null
      },
      replaceUrl: false
    });
  }

  loadEvents(showMore?: boolean) {
    this.eventsService
      .getEvents<Match>(
        this.eventCategoriesIds?.length ? this.eventCategoriesIds : [this.sportId],
        this.page++,
        20,
        !!this.selectedBetType ? FetchEventBetTypesMode.Specified : FetchEventBetTypesMode.Default,
        !!this.selectedBetType ? this.selectedBetType.id : null,
        this.oddsFilter
      )
      .pipe(
        takeUntil(merge(this.destroy$, this.route.params.pipe(skip(1)), this.filterChanged$)),
        finalize(() => {
          this.updateLoadingState(false, showMore);
          this.cdRef.markForCheck();
        })
      )
      .subscribe(({ result, hasMore }) => {
        this.events = [...this.events, ...result];
        this.hasMore = hasMore;
        this.restoreScrollPositionToLastEvent();
        this.updateEventsSubscriptions();
      });
  }

  loadPopularEvents(showMore?: boolean) {
    this.page++;

    this.eventsService
      .getPopularSportEvents(this.page * 10, this.sportId, !!this.selectedBetType ? this.selectedBetType.id : null)
      .pipe(
        takeUntil(merge(this.destroy$, this.route.params.pipe(skip(1)), this.filterChanged$)),
        finalize(() => {
          this.updateLoadingState(false, showMore);
          this.cdRef.markForCheck();
        })
      )
      .subscribe(events => {
        this.events = events;
        this.hasMore = events.length < (this.operatorConfiguration?.onlineConfiguration?.maxPopularMatchesCount ?? 40);
        this.restoreScrollPositionToLastEvent();
        this.updateEventsSubscriptions();
      });
  }

  trackEventBetType(_index: number, eventBetType: EventWithEventBetTypes<Match, EventBetType>) {
    return eventBetType.id;
  }

  onBetTypeSelected(betType: BetType, updateUrlQueryParams = true) {
    this.isChangingFilters = true;
    this.selectedBetType = betType;
    if (updateUrlQueryParams) {
      // refresh path without reloading the page
      var url = this.router
        .createUrlTree([], {
          queryParams: {
            ...this.params,
            betType: this.selectedBetType?.id,
            oddsFilter: this.oddsFilter,
            eventCategoriesIds:
              this.eventCategoriesIds && this.eventCategoriesIds.join(',')?.length > 0
                ? this.eventCategoriesIds.join(',')
                : null
          }
        })
        .toString();
      window.history.pushState({}, '', url);
    }

    this.reloadEvents();
  }

  onOddsFilterSelected(odds: number): void {
    this.isChangingFilters = true;
    this.oddsFilter = odds;
    this.toggleOddsFilter();
    this.setFiltersOnNavigation();
    this.reloadEvents();
  }

  onEventCategoriesFilterChanges(event: { eventCategories: EventCategory[]; applied: boolean }): void {
    if (event.applied) {
      this.eventCategoriesFilter = event.eventCategories;
      this.eventCategoriesIds = event.eventCategories.map(ec => ec.id);

      this.eventCategoriesFilterActive = false;
      this.bcService.broadcast<OpenCloseState>(ApplicationEvent.OverlayStateChange, 'close');
      this.setFiltersOnNavigation();
      this.reloadEvents();
    }

    this.eventCategoriesSelectionCount = event.eventCategories.length;
  }

  private restoreScrollPositionToLastEvent(): void {
    const lastEventId: number = this.eventsService.lastPositionEventId;

    if (!lastEventId) {
      return;
    }

    const previousRoute: string = sessionStorage.getItem('previous_route') ?? '';
    const comesFromEventDetail: boolean = previousRoute.includes('/event/');
    const isSameEntryPoint: boolean = this.eventsService.lastPositionEntryPointId === this.sportId;
    const shouldRestore: boolean = comesFromEventDetail && isSameEntryPoint;

    this.eventsService.clearLastEvent();

    if (!shouldRestore) {
      return;
    }

    this.zone.onStable.pipe(take(1)).subscribe(() => {
      const eventElement: HTMLElement | null = document.getElementById(`Event_Item_${lastEventId}`);

      if (eventElement) {
        this.scrollToElement(eventElement);
      }
    });
  }

  private scrollToElement(element: HTMLElement): void {
    const NAVBAR_OFFSET = -55;
    const scrollTarget = element.getBoundingClientRect().top + window.pageYOffset + NAVBAR_OFFSET;
    window.scrollTo({
      top: scrollTarget,
      behavior: 'smooth'
    });
  }
}
