import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit } from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { NavigationStart, Router } from '@angular/router';
import { finalize, filter, takeUntil } from 'rxjs/operators';
import { ApplicationEvent, BroadcastingService, DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { Media, MediaService } from '@honoregaming/ui';
import { OpenCloseState } from '@honoregaming/types';
import { TopWinBet, TopWinScope } from 'projects/core/hg-types/models/top-win-bets';
import { TopWinBetService } from '../../services/top-win-bet-service';
import { TelemetryService } from '@honoregaming/customer-core';

@Component({
  selector: 'hg-top-win-bets',
  templateUrl: './top-win-bets.component.html',
  styleUrls: ['./top-win-bets.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TopWinBetsComponent extends DestroySubject implements OnInit {
  bet?: TopWinBet;
  onlineTopWinBets: TopWinBet[] = [];
  retailTopWinBets: TopWinBet[] = [];
  topWinScope: TopWinScope = TopWinScope.Online;
  topWinBetsDisplayedCount?: number;

  displayPopup: boolean = false;
  isLoading: boolean = false;
  displayScopeSelection: boolean = false;

  TopWinScope = TopWinScope;
  Media = Media;

  private readonly TOP_WIN_BETS_LG_COUNT: number = 4;
  private readonly TOP_WIN_BETS_DEFAULT_COUNT: number = 5;

  constructor(
    protected readonly i18nService: I18nService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly topWinBetService: TopWinBetService,
    private readonly mediaService: MediaService,
    private readonly bcService: BroadcastingService,
    private readonly router: Router,
    private readonly telemetryService: TelemetryService,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(operatorConfigurationToken) public readonly operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.initTopWinScope();
    this.subscribeToMedia();
    this.subscribeToRouteChanges();
    this.closeOverlay();
    this.displayScopeSelection =
      this.operatorConfiguration.topWinBetsConfiguration.displayOnline &&
      this.operatorConfiguration.topWinBetsConfiguration.displayRetail;
  }

  get displayedTopWinBets(): TopWinBet[] {
    const bets: TopWinBet[] = this.topWinScope === TopWinScope.Retail ? this.retailTopWinBets : this.onlineTopWinBets;

    return bets.slice(0, this.topWinBetsDisplayedCount);
  }

  select(bet: TopWinBet): void {
    if (bet.betSystem) {
      this.telemetryService.trackEvent('big_winners_interaction', {
        location: this.mediaService.media >= Media.lg ? 'sidebar' : 'slider',
        betSystemId: bet.betSystem.id
      });
      this.bet = bet;
      this.displayPopup = true;
      this.fixBody();
    }
  }

  closePopup(): void {
    this.displayPopup = false;
    this.releaseBody();
    this.closeOverlay();
  }

  changeScope(scope: TopWinScope): void {
    this.topWinScope = scope;
    this.load();
  }

  private initTopWinScope(): void {
    this.topWinScope = this.resolveTopWinScope();
    this.load();
  }

  private subscribeToRouteChanges(): void {
    this.router.events
      .pipe(
        filter(event => event instanceof NavigationStart),
        takeUntil(this.destroy$)
      )
      .subscribe(() => {
        if (this.displayPopup) {
          this.closePopup();
          this.cdRef.markForCheck();
        }
      });
  }

  private subscribeToMedia(): void {
    this.mediaService?.media$.pipe(takeUntil(this.destroy$)).subscribe(media => {
      this.topWinBetsDisplayedCount = media >= Media.lg ? this.TOP_WIN_BETS_LG_COUNT : this.TOP_WIN_BETS_DEFAULT_COUNT;
    });
  }

  private resolveTopWinScope(): TopWinScope {
    if (!this.operatorConfiguration.topWinBetsConfiguration) {
      return TopWinScope.Online;
    }

    const { displayOnline, displayRetail } = this.operatorConfiguration.topWinBetsConfiguration;
    const isRetailOnly: boolean = !displayOnline && displayRetail;

    return isRetailOnly ? TopWinScope.Retail : TopWinScope.Online;
  }

  private closeOverlay(): void {
    this.bcService.broadcast<OpenCloseState>(ApplicationEvent.OverlayStateChange, 'close');
  }

  private load(): void {
    if (this.hasCachedBetsForBothScopes()) {
      return;
    }

    this.isLoading = true;

    this.topWinBetService
      .getTopWinBets(this.topWinScope)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(response => {
        this.setTopWinBets(response);
      });
  }

  private hasCachedBetsForBothScopes(): boolean {
    return this.displayScopeSelection && this.onlineTopWinBets.length > 0 && this.retailTopWinBets.length > 0;
  }

  private setTopWinBets(bets: TopWinBet[]): void {
    if (this.topWinScope === TopWinScope.Retail) {
      this.retailTopWinBets = bets;
    } else {
      this.onlineTopWinBets = bets;
    }
  }

  private fixBody(): void {
    this.document.documentElement.classList.add('hidden');
  }

  private releaseBody(): void {
    this.document.documentElement.classList.remove('hidden');
  }
}
