import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Input } from '@angular/core';
import { zip, merge } from 'rxjs';
import { Async, BroadcastingService, PushService, BetLinesMapperService } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { finalize, map, skip, takeUntil, tap, delay } from 'rxjs/operators';
import { Match, EventCategory, EventWithEventBetType, EventWithEventBetTypes, EventBetType } from '@honoregaming/types';
import { BetSlipBetLinesService, BetSlipService } from '@honoregaming/betslip';
import { EventCategoriesService, EventsService, EventsMapperService } from '@honoregaming/events';
import { EventsWithEventBetTypesComponentBase } from '@honoregaming/sports-ui';

@Component({
  selector: 'hg-bets-home-live',
  templateUrl: './bets-home-live.component.html',
  styleUrls: ['./bets-home-live.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetsHomeLiveComponent extends EventsWithEventBetTypesComponentBase implements OnInit {
  @Input() isHomePage: boolean;

  liveEventsWithEventBetTypes: {
    events: EventWithEventBetTypes<Match>[];
    entryPointDisplayPriority?: number;
    entryPointLiveDisplayPriority?: number;
    entryPointId: number;
    categories: string[];
  }[];
  liveDisplayedEventsWithEventBetTypes: {
    events: EventWithEventBetTypes<Match>[];
    entryPointId: number;
    categories: string[];
  }[];
  entryPoints: { category: EventCategory; liveCount: number }[] = [];

  hasLoadedEvents = false;
  loadingEvents = false;
  loadingNextEvents = true;
  totalLivesCounter: number;

  selectedEntryPoint?: number;

  constructor(
    private eventsService: EventsService,
    private eventCategoriesService: EventCategoriesService,
    protected i18nService: I18nService,
    protected betSlipService: BetSlipService,
    protected cdRef: ChangeDetectorRef,
    protected pushService: PushService,
    protected bcService: BroadcastingService,
    protected eventsMapperService: EventsMapperService,
    protected betLinesMapperService: BetLinesMapperService,
    protected betSlipBetLinesService: BetSlipBetLinesService
  ) {
    super(
      i18nService,
      betSlipService,
      pushService,
      cdRef,
      bcService,
      eventsMapperService,
      betLinesMapperService,
      betSlipBetLinesService
    );
  }

  ngOnInit() {
    super.ngOnInit();
    this.loadLiveEvents();
  }

  trackByFn(_index: number, item: EventWithEventBetTypes<Match, EventBetType>) {
    return item.id;
  }

  @Async()
  private loadLiveEvents() {
    this.loadingEvents = !this.liveEventsWithEventBetTypes;
    zip(this.eventCategoriesService.getEntryPoints(), this.eventsService.getLiveSportsEvents())
      .pipe(
        takeUntil(merge(this.destroy$, this.i18nService.languageChanged$.pipe(skip(1)))),
        map(result => {
          const entryPoints = result[0];
          this.liveEventsWithEventBetTypes = result[1].reduce(
            (
              groups: {
                events: EventWithEventBetType<Match>[];
                entryPointId: number;
                categoryPath: string;
                categories: string[];
              }[],
              e: EventWithEventBetType<Match>
            ) => {
              const targetGroup = groups.find(t => t.categoryPath === e.categoryPath);
              if (targetGroup) {
                targetGroup.events.push(e);
              } else {
                groups.push({
                  categories: e.categories,
                  categoryPath: e.categoryPath,
                  entryPointId: e.entryPointId,
                  events: [e]
                });
              }

              return groups;
            },
            []
          );

          this.entryPoints = [];
          entryPoints.forEach(e => {
            const liveCount = result[1].filter(x => x.entryPointId === e.id).length;
            if (liveCount) {
              this.entryPoints.push({
                category: e,
                liveCount: liveCount
              });
            }
          });

          if (this.entryPoints?.length) {
            this.totalLivesCounter = this.entryPoints
              .map(a => a.liveCount)
              .reduce(function (a, b) {
                return a + b;
              });
          }

          this.events = [...this.liveEventsWithEventBetTypes.map(e => e.events).reduce((acc, x) => acc.concat(x), [])];

          this.subscribeToPushChanges();
          this.subscribeToBetSlip();
          this.registerToPushChanges();
          this.updateSelectedItems();
          this.changeEntryPoint(this.selectedEntryPoint, false);

          this.cdRef.markForCheck();
        }),
        delay(200),
        tap(() => (this.hasLoadedEvents = true)),
        finalize(() => {
          this.loadingEvents = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe();
  }

  changeEntryPoint(entryPointId?: number, isManualChange = true) {
    this.selectedEntryPoint = isManualChange && this.selectedEntryPoint === entryPointId ? undefined : entryPointId;

    if (!this.selectedEntryPoint) {
      this.liveDisplayedEventsWithEventBetTypes = this.liveEventsWithEventBetTypes;
    } else {
      this.liveDisplayedEventsWithEventBetTypes = this.liveEventsWithEventBetTypes.filter(
        x => x.entryPointId === this.selectedEntryPoint
      );
    }
  }

  onEventChangedToLiveState() {
    this.loadLiveEvents();
  }

  showNextLives() {
    this.loadingNextEvents = false;
  }
}
