import { Component, OnInit, ChangeDetectionStrategy, Input } from '@angular/core';
import { Router } from '@angular/router';
import { ManualOddsBoost } from '@honoregaming/types';
import { DateTime } from 'luxon';

@Component({
  selector: 'hg-manual-odds-group',
  templateUrl: './manual-odds-group.component.html',
  styleUrls: ['./manual-odds-group.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ManualOddsGroupComponent implements OnInit {
  @Input() title!: string;
  @Input() iconUrl?: string;
  @Input() entryPointId?: number;
  @Input() headerLink?: string;
  @Input() date!: DateTime;
  @Input() list!: (ManualOddsBoost & { selected: boolean })[];
  @Input() defaultMaxDisplayed: number = 3;

  displayedList: (ManualOddsBoost & { selected: boolean })[] = [];
  hiddenCount: number = 0;

  constructor(private router: Router) {}

  ngOnInit(): void {
    this.displayedList = this.list.slice(0, this.defaultMaxDisplayed);
    this.hiddenCount = this.list.length - this.displayedList.length;
  }

  displayAll(): void {
    this.displayedList = this.hiddenCount > 0 ? this.list : this.list.slice(0, this.defaultMaxDisplayed);
    this.hiddenCount = this.list.length - this.displayedList.length;
  }

  navigateToEvent(): void {
    if (this.headerLink) {
      this.router.navigate([this.headerLink]);
    }
  }
}
