import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { Images } from '@honoregaming/types';

@Component({
  selector: 'hg-event-banner',
  templateUrl: './event-banner.component.html',
  styleUrls: ['./event-banner.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventBannerComponent {
  @Output() bannerClicked = new EventEmitter();
  @Input() bannerImages: Images;

  constructor() {}

  handleClickOnBanner(): void {
    this.bannerClicked.emit();
  }
}
