import { Component, OnInit, ChangeDetectionStrategy, Input, ChangeDetectorRef } from '@angular/core';
import { BetLine, BetSlipBetLinesService, BetSlipLinesInfo, BetSlipService } from '@honoregaming/betslip';
import { DestroySubject, PushService } from '@honoregaming/core';
import { EventsService } from '@honoregaming/events';
import { I18nService } from '@honoregaming/i18n';
import { ManualOddsBoost } from '@honoregaming/types';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-manual-odds-content',
  templateUrl: './manual-odds-content.component.html',
  styleUrls: ['./manual-odds-content.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ManualOddsContentComponent extends DestroySubject implements OnInit {
  @Input() manualOdds!: ManualOddsBoost & { selected: boolean };
  @Input() displayDate?: boolean = true;

  currentLanguage: string = this.i18nService.currentLanguageCode;
  fallbackLanguage: string = this.i18nService.fallbackLanguageCode;
  disabled: boolean = false;

  constructor(
    private readonly betSlipService: BetSlipService,
    private readonly i18nService: I18nService,
    private readonly pushService: PushService,
    private readonly eventsService: EventsService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly betSlipBetLinesService: BetSlipBetLinesService
  ) {
    super();
  }

  ngOnInit(): void {
    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe((language: string) => {
      this.currentLanguage = language;
    });

    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe((betSlipLinesInfo: BetSlipLinesInfo) => {
      const selectedManualOddsBoostIds: number[] = betSlipLinesInfo.lines
        .filter((line: BetLine) => !!line.manualOddsBoostId)
        .map((line: BetLine) => line.manualOddsBoostId ?? 0);
      this.manualOdds.selected = selectedManualOddsBoostIds.includes(this.manualOdds.id);
      this.disabled = betSlipLinesInfo.lines.some((betLine: BetLine) => betLine.isBetCompletion);
      this.cdRef.markForCheck();
    });

    this.subscribeToPushChanges();
  }

  subscribeToPushChanges() {
    this.pushService.manualOddsChanged$.pipe(takeUntil(this.destroy$)).subscribe(changed => {
      if (changed && changed.oddsBoostId && changed.changes) {
        this.eventsService.updateManualOddsBoostInCache(
          changed.oddsBoostId,
          changed.changes.baseAmount,
          changed.changes.minimumAmountIncrement,
          changed.changes.maximumAmount,
          changed.changes.newOdds,
          changed.changes.expirationDate
        );

        if (this.manualOdds.id === changed.oddsBoostId) {
          if (changed.changes.baseAmount) {
            this.manualOdds.baseAmount = changed.changes.baseAmount;
          }

          if (changed.changes.minimumAmountIncrement) {
            this.manualOdds.minimumAmountIncrement = changed.changes.minimumAmountIncrement;
          }

          if (changed.changes.maximumAmount) {
            this.manualOdds.maximumAmount = changed.changes.maximumAmount;
          }

          if (changed.changes.expirationDate) {
            this.manualOdds.expirationDate = changed.changes.expirationDate;
          }

          if (changed.changes.newOdds) {
            this.manualOdds.fixedOdds = changed.changes.newOdds;
          }
        }

        this.cdRef.markForCheck();
      }
    });
  }

  toggleManualOddsBoost(): void {
    this.betSlipBetLinesService.toggleManualOddsBoost(this.manualOdds);
    this.cdRef.markForCheck();
  }

  getDisplayName(): string | undefined {
    // Try to get local name
    let manualOddsName = this.manualOdds.names[this.currentLanguage];

    // If empty | null | undefined, try fallback language > then name
    if (!manualOddsName) {
      manualOddsName = this.manualOdds.names[this.fallbackLanguage];
    }

    if (!manualOddsName) {
      manualOddsName = this.manualOdds.name;
    }

    return manualOddsName;
  }
}
