import {
  Component,
  Input,
  Output,
  EventEmitter,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  HostBinding,
  ViewChild,
  ElementRef
} from '@angular/core';
import { BetTypeGroup, Match } from '@honoregaming/types';

@Component({
  selector: 'hg-event-bet-types-filters',
  templateUrl: './event-bet-types-filters.component.html',
  styleUrls: ['./event-bet-types-filters.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventBetTypesFiltersComponent {
  @Input() event!: Match;
  @Input() filters: string[] = [];
  @Input() entryPointId!: number;
  @Input() hasNewPlayerStatsBetType: boolean = false;
  @Input() isStickyFilters: boolean = false;
  @Input() stickyTopOffset?: number;
  @Input() isBetBuilderToggled: boolean = false;

  @Output() filterChanged = new EventEmitter<{
    activeFilter: BetTypeGroup;
  }>();

  @Output() toggleBetBuilderEvent = new EventEmitter<boolean>();

  @HostBinding('class.is-sticky') get stickyClass(): boolean {
    return this.isStickyFilters;
  }

  @HostBinding('style.top.px') get stickyTop(): number | undefined {
    return this.isStickyFilters ? this.stickyTopOffset : undefined;
  }

  @ViewChild('filterContainer') filterContainerRef?: ElementRef;

  activeFilter: BetTypeGroup = 0;
  activeFilterSet: Record<string, boolean> = {};

  filterDragging: boolean = false;
  filterDragStartX: number = 0;
  filterScrollLeft: number = 0;

  constructor(private readonly cdRef: ChangeDetectorRef) {}

  toggleFilter(filter: string): void {
    const filterValue = BetTypeGroup[filter as keyof typeof BetTypeGroup];
    this.activeFilter = this.activeFilter === filterValue ? BetTypeGroup.None : filterValue;

    this.activeFilterSet = this.filters.reduce((acc: Record<string, boolean>, filter: string) => {
      acc[filter] = BetTypeGroup[filter as keyof typeof BetTypeGroup] === this.activeFilter;
      return acc;
    }, {} as Record<string, boolean>);

    this.filterChanged.emit({
      activeFilter: this.activeFilter
    });

    this.cdRef.markForCheck();
  }

  resetFilter(filter: string): void {
    this.toggleFilter(filter);
  }

  onFilterDragStart(mouseEvent: MouseEvent): void {
    this.filterDragging = true;
    this.filterDragStartX = mouseEvent.pageX - this.filterContainerRef.nativeElement.offsetLeft;
    this.filterScrollLeft = this.filterContainerRef.nativeElement.scrollLeft;
  }

  onFilterDrag(mouseEvent: MouseEvent): void {
    if (this.filterDragging) {
      mouseEvent.preventDefault();
      this.filterContainerRef.nativeElement.scrollLeft =
        this.filterScrollLeft -
        (mouseEvent.pageX - this.filterContainerRef.nativeElement.offsetLeft - this.filterDragStartX);
    }
  }

  onFilterDragEnd(): void {
    this.filterDragging = false;
  }

  toggleBetBuilder(isBetBuilderToggled: boolean): void {
    this.toggleBetBuilderEvent.emit(isBetBuilderToggled);
  }
}
