import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { EventsByEventCategoryComponent, BetsHomeLiveComponent, SearchComponent } from './containers';
import { SidebarComponent } from './components/sidebar/sidebar.component';
import { LayoutComponent } from './containers/layout/layout.component';
import { BetSlipIconComponent } from '@honoregaming/betslip';
import { EventWithEventBetTypesComponent } from './containers/event-with-event-bet-types/event-with-event-bet-types.container';
import { OddsBoostsComponent } from './containers/odds-boosts/odds-boosts.component';
import { ManualOddsBoostsComponent } from './containers/manual-odds-boosts/manual-odds-boosts.component';
import { FeaturesGuard } from '@honoregaming/core';
import { CategoryNavigationComponent } from '@honoregaming/sports-ui';
import { SportsOrderedHomeComponent } from './containers/sports-ordered-home/sports-ordered-home.component';
import { SearchFieldComponent } from 'projects/core/hg-templating/src/lib/components/search-field/search-field.component';

const routes: Routes = [
  {
    path: '',
    component: LayoutComponent,
    children: [
      { path: '', component: SportsOrderedHomeComponent },
      {
        path: 'live',
        children: [
          { path: '', component: BetsHomeLiveComponent },
          {
            path: 'event/:event',
            component: EventWithEventBetTypesComponent
          },
          {
            path: 'event/:homeTeamName-:awayTeamName-m:event',
            component: EventWithEventBetTypesComponent
          }
        ]
      },
      {
        path: 'search/:search',
        component: SearchComponent
      },
      { path: 'event/:event', component: EventWithEventBetTypesComponent },
      {
        path: 'event/:homeTeamName-:awayTeamName-m:event',
        component: EventWithEventBetTypesComponent
      },
      {
        path: 'odds-boosts',
        component: OddsBoostsComponent,
        canActivate: [FeaturesGuard],
        data: { featureName: 'OddsBoost' }
      },
      {
        path: 'manual-odds-boosts',
        component: ManualOddsBoostsComponent,
        canActivate: [FeaturesGuard],
        data: { featureName: 'ManualOdds' }
      },
      { path: 'menu/:entryPointId', component: CategoryNavigationComponent },
      { path: ':sport', component: EventsByEventCategoryComponent },
      { path: ':sport/:rootCategory/:category', component: EventsByEventCategoryComponent, data: { closeMenu: true } },
      { path: ':sport/:rootCategory', component: EventsByEventCategoryComponent }
    ]
  },
  { path: '', outlet: 'sidebar', component: SidebarComponent },
  { path: '', outlet: 'betslipicon', component: BetSlipIconComponent },
  { path: '', outlet: 'search', component: SearchFieldComponent }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class HgSportsEventRoutingModule {}
