import {
  Component,
  ChangeDetectionStrategy,
  HostBinding,
  Optional,
  ChangeDetectorRef,
  Input,
  Inject,
  PLATFORM_ID,
  OnInit
} from '@angular/core';
import { EventCategoriesNavigationComponent } from '../event-categories-navigation.component';
import { EventCategoriesService, EventsService } from '@honoregaming/events';
import { MediaService } from '@honoregaming/ui';
import { I18nService } from '@honoregaming/i18n';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { Scope, scopeToken, kioskToken } from '@honoregaming/core';
import { isPlatformServer } from '@angular/common';
import { Feature, operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { EventTab } from '@honoregaming/types';
import { takeUntil, finalize } from 'rxjs/operators';

@Component({
  selector: 'hg-sports-ui-desktop-event-categories-navigation',
  templateUrl: './event-categories-navigation.component.html',
  styleUrls: ['./event-categories-navigation.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DesktopEventCategoriesNavigationComponent extends EventCategoriesNavigationComponent implements OnInit {
  @HostBinding('class') class = 'desktop-navigation-menu';

  Scope = Scope;
  isServer = isPlatformServer(this.platformId);

  displayLinkOddsBoosts: boolean = false;
  displayLinkManualOdds: boolean = false;
  hasOddsBoosts = false;
  hasManualOdds = false;

  @Input()
  showLiveEntry = false;

  @Input()
  eventTabs: EventTab[];

  currentLanguage: string = this.i18nService.currentLanguageCode;

  hasOddsBoostFeature = this.operatorConfiguration.operatorFeatures.indexOf('OddsBoost') !== -1;
  hasManualOddsFeature = this.operatorConfiguration.operatorFeatures.indexOf('ManualOdds') !== -1;

  constructor(
    @Inject(scopeToken) scope: Scope,
    eventCategoriesService: EventCategoriesService,
    @Optional() mediaService: MediaService,
    cdRef: ChangeDetectorRef,
    i18nService: I18nService,
    route: ActivatedRoute,
    protected eventsService: EventsService,
    private router: Router,
    @Inject(kioskToken) public isKiosk: boolean,
    @Inject(PLATFORM_ID) private platformId,
    @Inject(operatorConfigurationToken) public operatorConfiguration: OperatorConfiguration
  ) {
    super(eventCategoriesService, eventsService, mediaService, cdRef, i18nService, route, scope, operatorConfiguration);
  }

  ngOnInit(): void {
    super.ngOnInit();
    if (this.hasManualOddsFeature) {
      this.getManualOddsBoosts();
    }

    if (this.hasOddsBoostFeature) {
      this.getOddsBoosts();
    }

    this.checkOddsLink();

    //update the currentEntryPoint when any url changes on event category navigation
    this.router.events.subscribe(e => {
      if (e instanceof NavigationEnd) {
        var url = this.route.snapshot['_routerState'].url.split('?')[0];
        if (url === '/sports' || url === '/sports/live' || this.route.firstChild.snapshot?.params === null) {
          this.currentEntryPoint = null;
        }
        this.route.firstChild?.paramMap.subscribe(_ => {
          var sportId = this.route.firstChild?.snapshot?.params?.sport;
          if (sportId) {
            var entryPoint = this.entryPoints?.filter(x => x.root.id === +sportId);
            if (entryPoint?.length === 1) {
              this.currentEntryPoint = entryPoint[0];
              this.toggleEntryPoint(this.currentEntryPoint);
            }
          }
          this.cdRef.markForCheck();
        });
      }
    });

    if (this.hasOddsBoostFeature) {
      this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(l => {
        this.currentLanguage = l;
        this.getOddsBoosts();
        this.cdRef.markForCheck();
      });
    }
  }

  getManualOddsBoosts() {
    this.eventsService
      .getManualOddsBoosts()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(manualOddsBoosts => {
        if (manualOddsBoosts?.result?.length ?? 0 > 0) {
          this.hasManualOdds = true;
        }
      });
  }

  getOddsBoosts() {
    this.eventsService
      .getOddsBoosts(this.currentLanguage)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(oddsBoosts => {
        if (oddsBoosts && oddsBoosts.length > 0) {
          this.hasOddsBoosts = true;
        }
      });
  }

  includesPath(string): boolean {
    return this.router.url.includes(string);
  }

  private checkOddsLink() {
    if (!this.eventTabs) {
      return;
    }
    this.displayLinkOddsBoosts = this.operatorConfiguration.operatorFeatures?.indexOf(Feature.OddsBoost) > -1;
    this.displayLinkManualOdds = this.operatorConfiguration.operatorFeatures?.indexOf(Feature.ManualOdds) > -1;
  }
}
