import { ChangeDetectionStrategy, ChangeDetectorRef, Component, OnInit } from '@angular/core';
import { BetLine, BetSlipBetLinesService, BetSlipService } from '@honoregaming/betslip';
import { Async, AsyncTrigger, DestroySubject, PushService, updateOddsBoostAfterPush } from '@honoregaming/core';
import { EventsService } from '@honoregaming/events';
import { I18nService } from '@honoregaming/i18n';
import { OddsBoost } from '@honoregaming/types';
import { merge } from 'rxjs';
import { finalize, skip, takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-odds-boosts',
  templateUrl: './odds-boosts.component.html',
  styleUrls: ['./odds-boosts.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OddsBoostsComponent extends DestroySubject implements OnInit {
  oddsBoosts: (OddsBoost & { nextEventDate: Date; selected: boolean })[] = [];

  selectedOddsBoostIds: number[] = [];
  disabled = false;
  isLoading = false;

  currentLanguage: string = this.i18nService.currentLanguageCode;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  constructor(
    private eventsService: EventsService,
    private betSlipService: BetSlipService,
    private i18nService: I18nService,
    private pushService: PushService,
    private cdRef: ChangeDetectorRef,
    private betSlipBetLinesService: BetSlipBetLinesService
  ) {
    super();
  }

  ngOnInit() {
    this.getOddsBoosts();

    this.i18nService.languageChanged$.subscribe(l => {
      this.currentLanguage = l;
      this.getOddsBoosts();
      this.cdRef.markForCheck();
    });

    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(betSlip => {
      this.selectedOddsBoostIds = betSlip.lines.filter(l => !!l.oddsBoostId).map(l => l.oddsBoostId);
      this.disabled = betSlip.lines.some((betLine: BetLine) => betLine.isBetCompletion);
      this.updateSelectedOddsBoosts();

      this.cdRef.markForCheck();
    });

    this.subscribeToPushChanges();
  }

  @Async()
  getOddsBoosts() {
    this.isLoading = true;
    this.eventsService
      .getOddsBoosts(this.currentLanguage)
      .pipe(
        takeUntil(merge(this.destroy$, this.i18nService.languageChanged$.pipe(skip(1)))),
        finalize(() => {
          this.updateSelectedOddsBoosts();
          this.isLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(oddsBoosts => {
        this.oddsBoosts = oddsBoosts.map(ob => {
          return {
            ...ob,
            selected: false,
            active: true,
            nextEventDate: ob.details.reduce((current, next) =>
              current.event.expectedStart < next.event.expectedStart ? current : next
            ).event.expectedStart
          };
        });

        const eventBetTypesIds = this.oddsBoosts.map(ob => ob.details.map(d => d.eventBetType.id));
        if (eventBetTypesIds?.length) {
          this.pushService.subscribeToOdds(
            eventBetTypesIds.reduce((a, b) => a.concat(b)),
            []
          );
        }
      });
  }

  toggleOddsBoost(oddsBoost: OddsBoost & { nextEventDate: Date; selected: boolean }) {
    this.betSlipBetLinesService.toggleOddsBoost(oddsBoost);
  }

  private updateSelectedOddsBoosts() {
    if (this.oddsBoosts.length) {
      for (let i = 0; i < this.oddsBoosts.length; i++) {
        this.oddsBoosts[i].selected = false;

        this.selectedOddsBoostIds.forEach(ob => {
          if (this.oddsBoosts[i].id === ob) {
            this.oddsBoosts[i].selected = true;
          }
        });
      }
    }
  }

  trackOddsBoost(_index, item: OddsBoost) {
    return item.id;
  }

  subscribeToPushChanges() {
    this.pushService.eventBetTypeChanged$.pipe(takeUntil(this.destroy$)).subscribe(changed => {
      let hasChanged = false;

      this.oddsBoosts.forEach(ob => (hasChanged = updateOddsBoostAfterPush(ob, changed) || hasChanged));

      if (hasChanged) {
        this.cdRef.markForCheck();
      }
    });
  }
}
