import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject, Optional } from '@angular/core';
import { combineLatest, Observable } from 'rxjs';
import { take, takeUntil } from 'rxjs/operators';
import { ShareCodeComponent } from '@honoregaming/customer-ui';
import {
  DialogService,
  kioskToken,
  BroadcastingService,
  hasFlag,
  DestroySubject,
  CompleteMyBetService
} from '@honoregaming/core';
import { BetradarFeatureType, ScoreWidgetType } from '@honoregaming/configuration';
import {
  customerOperatorConfigurationToken,
  CustomerOperatorConfiguration,
  AuthService,
  CodeType,
  Me
} from '@honoregaming/customer-core';
import { Media, MediaService, MessageService } from '@honoregaming/ui';
import { I18nService } from '@honoregaming/i18n';
import { BetSlipService } from '@honoregaming/betslip';
import { BetCodeGenerated } from '@honoregaming/types';

@Component({
  selector: 'hg-sport-sidebar',
  templateUrl: './sidebar.component.html',
  styleUrls: ['./sidebar.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SidebarComponent extends DestroySubject implements OnInit {
  betSlipActive: boolean = false;
  sourceRef?: string;
  me?: Me;
  topWinBetsActivated: boolean = false;
  hasAtLeastOneBetLine: boolean = false;

  brSubscriptionId: string = this.operatorConfiguration.scoreWidgetConfiguration?.configuration?.subscriptionId;
  liveTrackerAvailable: boolean = hasFlag(
    this.operatorConfiguration.features.betradarFeatures,
    BetradarFeatureType.LiveTracker
  );

  ScoreWidgetType = ScoreWidgetType;

  displayCompleteMyBetTutorial: boolean = false;

  constructor(
    private readonly dialogService: DialogService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly broadcastingService: BroadcastingService,
    private readonly messageService: MessageService,
    protected readonly authService: AuthService,
    private readonly i18nService: I18nService,
    private readonly betSlipService: BetSlipService,
    private readonly completeMyBetService: CompleteMyBetService,
    @Inject(customerOperatorConfigurationToken)
    public readonly operatorConfiguration: CustomerOperatorConfiguration,
    @Inject(kioskToken) public readonly isKiosk: boolean,
    @Optional() private readonly mediaService: MediaService
  ) {
    super();
  }

  ngOnInit(): void {
    this.listenToBetSlipDialog();
    this.listenToLmtWidgetEvents();
    this.listenToAuthMe();
    this.subscribeToTopWinBetsVisibility();
    this.listenToCompleteMyBetTutorial();
  }

  openBetSlip(): void {
    if (!this.displayCompleteMyBetTutorial) {
      this.dialogService.toggleDialog('betslip', !this.betSlipActive);
    }
  }

  closeBetSlip(): void {
    this.dialogService.toggleDialog('betslip', false);
  }

  betCodeGenerated(betCode: BetCodeGenerated): void {
    const codeNameObservable: Observable<string> = this.i18nService.translate('BETCODE.BETCODE');
    const shareUrl: string = `${this.operatorConfiguration.global.customerUrl}/?betcode=${betCode.code}`;

    const shareMessageObservable: Observable<string> = this.i18nService.translate(
      betCode.isOddsBoost ? 'BETCODE.SHARE_ODDSBOOST_MESSAGE' : 'BETCODE.SHARE_MESSAGE_TEMPLATE',
      betCode.totalOdds,
      betCode.code,
      this.operatorConfiguration.name,
      shareUrl,
      betCode.isOddsBoost ? betCode.oddsBoostName : null
    );

    combineLatest([codeNameObservable, shareMessageObservable])
      .pipe(take(1))
      .subscribe(([codeName, shareMessage]) => {
        let response = this.messageService.sendComponentMessage(ShareCodeComponent, {
          code: betCode.code,
          codeName: codeName,
          codeType: CodeType.BetCode,
          shareMessageTemplate: shareMessage + (betCode.isOddsBoost ? ' 🚀' : ' 🏆')
        });

        if (this.isKiosk) {
          response.closed.subscribe(() => this.betSlipService.clear());
        }
      });
  }

  hasBetLines(hasBetLines: boolean): void {
    this.hasAtLeastOneBetLine = hasBetLines;
  }

  private listenToBetSlipDialog(): void {
    this.dialogService
      .registerDialog('betslip')
      .pipe(takeUntil(this.destroy$))
      .subscribe(open => {
        this.betSlipActive = open;
        this.cdRef.markForCheck();
      });
  }

  private listenToLmtWidgetEvents(): void {
    this.broadcastingService
      .register<{ sourceRef: string }>('LMT.Widget.Show')
      .pipe(takeUntil(this.destroy$))
      .subscribe(event => {
        this.sourceRef = event.sourceRef;
        this.cdRef.markForCheck();
      });

    this.broadcastingService
      .register('LMT.Widget.Hide')
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        this.sourceRef = null;
        this.cdRef.markForCheck();
      });
  }

  private listenToAuthMe(): void {
    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      this.me = me;
      this.cdRef.markForCheck();
    });
  }

  private listenToCompleteMyBetTutorial(): void {
    this.completeMyBetService.displayTutorial$.pipe(takeUntil(this.destroy$)).subscribe(displayTutorial => {
      this.displayCompleteMyBetTutorial = displayTutorial;
      this.cdRef.markForCheck();
    });
  }

  private subscribeToTopWinBetsVisibility(): void {
    const { operatorFeatures, topWinBetsConfiguration } = this.operatorConfiguration;

    if (!operatorFeatures.includes('TopWinBets')) {
      return;
    }

    const hasDisplayMode: boolean = topWinBetsConfiguration.displayOnline || topWinBetsConfiguration.displayRetail;

    if (!hasDisplayMode) {
      return;
    }

    this.mediaService?.media$.pipe(takeUntil(this.destroy$)).subscribe(media => {
      this.topWinBetsActivated = media >= Media.lg;
      this.cdRef.markForCheck();
    });
  }
}
