import { Component, Input, ChangeDetectionStrategy, ChangeDetectorRef, OnInit, OnDestroy } from '@angular/core';
import { takeUntil, finalize } from 'rxjs/operators';
import { I18nService } from '@honoregaming/i18n';
import { DestroySubject, PushService } from '@honoregaming/core';
import { ManualOddsBoost, EventChangedModel, SelectableManualOddsBoost } from '@honoregaming/types';
import { BetSlipBetLinesService, BetSlipService } from '@honoregaming/betslip';
import { EventsService } from '@honoregaming/events';
import { ManualOddsList } from 'projects/core/hg-types/models/odds-boost/manual-odds-list.model';

@Component({
  selector: 'hg-event-manual-odds-boosts',
  templateUrl: './event-manual-odds-boosts.component.html',
  styleUrls: ['./event-manual-odds-boosts.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventManualBoostsComponent extends DestroySubject implements OnInit, OnDestroy {
  @Input() eventId!: number;
  @Input() currentLanguage!: string;

  manualOddsBoosts: SelectableManualOddsBoost[] = [];
  showMore: boolean = false;

  private selectedManualOddsBoostIds: number[] = [];

  constructor(
    private readonly eventsService: EventsService,
    private readonly betSlipService: BetSlipService,
    private readonly pushService: PushService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly i18nService: I18nService,
    private readonly betSlipBetLinesService: BetSlipBetLinesService
  ) {
    super();
  }

  ngOnInit(): void {
    this.loadManualOddsBoosts();
    this.subscribeToBetSlipChanges();
    this.subscribeToManualOddsChanges();
    this.subscribeToLanguageChanges();
  }

  get visibleBoosts(): SelectableManualOddsBoost[] {
    return this.showMore ? this.manualOddsBoosts : this.manualOddsBoosts.slice(0, 3);
  }

  get hasOverflow(): boolean {
    return this.manualOddsBoosts.length > 3;
  }

  toggleManualOddsBoost(manualOddsBoost: SelectableManualOddsBoost): void {
    this.betSlipBetLinesService.toggleManualOddsBoost(manualOddsBoost);
  }

  toggleShowMore(): void {
    this.showMore = !this.showMore;
  }

  private loadManualOddsBoosts(): void {
    this.eventsService
      .getManualOddsBoosts()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.updateSelectedState();
          this.cdRef.markForCheck();
        })
      )
      .subscribe((boosts: ManualOddsList) => {
        this.manualOddsBoosts = boosts.result
          .filter((mob: ManualOddsBoost) => mob.eventId === this.eventId)
          .map((mob: ManualOddsBoost) => ({
            ...mob,
            names: JSON.parse(mob.localizedName ?? "''"),
            selected: false,
            active: true
          }));
      });
  }

  private subscribeToBetSlipChanges(): void {
    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(betSlip => {
      this.selectedManualOddsBoostIds = betSlip.lines
        .filter(line => !!line.manualOddsBoostId)
        .map(line => line.manualOddsBoostId);

      this.updateSelectedState();
      this.cdRef.markForCheck();
    });
  }

  private subscribeToManualOddsChanges(): void {
    this.pushService.manualOddsChanged$.pipe(takeUntil(this.destroy$)).subscribe((changed: EventChangedModel) => {
      if (!changed?.oddsBoostId || !changed.changes) {
        return;
      }

      this.eventsService.updateManualOddsBoostInCache(
        changed.oddsBoostId,
        changed.changes.baseAmount,
        changed.changes.minimumAmountIncrement,
        changed.changes.maximumAmount,
        changed.changes.newOdds,
        changed.changes.expirationDate
      );

      if (!this.manualOddsBoosts.length) {
        return;
      }

      this.applyPushChanges(changed);
      this.cdRef.markForCheck();
    });
  }

  private subscribeToLanguageChanges(): void {
    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe((language: string) => {
      this.currentLanguage = language;
      this.cdRef.markForCheck();
    });
  }

  private applyPushChanges(changed: EventChangedModel): void {
    for (const mob of this.manualOddsBoosts) {
      if (mob.id !== changed.oddsBoostId) {
        continue;
      }

      const { baseAmount, minimumAmountIncrement, maximumAmount, expirationDate, newOdds } = changed.changes;

      if (baseAmount) {
        mob.baseAmount = baseAmount;
      }
      if (minimumAmountIncrement) {
        mob.minimumAmountIncrement = minimumAmountIncrement;
      }
      if (maximumAmount) {
        mob.maximumAmount = maximumAmount;
      }
      if (expirationDate) {
        mob.expirationDate = expirationDate;
      }
      if (newOdds) {
        mob.fixedOdds = newOdds;
      }
    }
  }

  private updateSelectedState(): void {
    const selectedIds: Set<number> = new Set(this.selectedManualOddsBoostIds);

    for (const boost of this.manualOddsBoosts) {
      boost.selected = selectedIds.has(boost.id);
    }
  }
}
