import { Component, ChangeDetectionStrategy, OnInit, Input, Output, EventEmitter } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { EventCategoriesService } from '@honoregaming/events';
import { EventCategory } from '@honoregaming/types';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-event-categories-filter',
  templateUrl: './event-categories-filter.component.html',
  styleUrls: ['./event-categories-filter.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventCategoriesFilterComponent extends DestroySubject implements OnInit {
  @Input() entryPointId: number;
  @Input() selectedEventCategoriesIds: number[];

  @Output() filterChanged = new EventEmitter<{ eventCategories: EventCategory[]; applied: boolean }>();

  topEventCategoriesActive = false;
  topEventCategoriesSelectionNumber = 0;
  topEventCategories: EventCategory[];
  eventCategories: (EventCategory & { opened: boolean; selectionNumber: number })[];
  moreEventCategories: (EventCategory & { opened: boolean; selectionNumber: number })[];
  showAllEventCategories = false;

  allEventCategories: { [id: number]: EventCategory & { opened: boolean; selectionNumber: number } };

  selectedEventCategories: EventCategory[] = [];

  constructor(private eventCategoriesService: EventCategoriesService) {
    super();
  }

  ngOnInit() {
    this.eventCategoriesService
      .getCategoriesForEntryPoint(this.entryPointId)
      .pipe(takeUntil(this.destroy$))
      .subscribe(ec => {
        var eventCategories = ec.map(e => {
          let selected = 0;
          e.subCategories = [
            ...e.subCategories.map(subE => {
              return { ...subE, isChecked: false };
            })
          ];
          if (this.selectedEventCategoriesIds && !!this.selectedEventCategoriesIds.length) {
            e.subCategories.forEach(subE => {
              if (this.selectedEventCategoriesIds.indexOf(subE.id) !== -1) {
                subE.isChecked = true;
                selected++;
                this.selectedEventCategories.push(subE);
              }
            });
          }

          return { ...e, opened: false, selectionNumber: selected };
        });

        this.allEventCategories = eventCategories.reduce((dico, ec) => ({ ...dico, [ec.id]: ec }), {});

        this.eventCategories = eventCategories.slice(0, 5);
        this.moreEventCategories = eventCategories.slice(5);

        this.topEventCategories = Array.prototype
          .concat(...this.eventCategories.map(ec => ec.subCategories))
          .sort((x, y) => (x.priority < y.priority ? -1 : 1))
          .splice(0, 5);

        this.topEventCategoriesSelectionNumber = this.topEventCategories.filter(e => e.isChecked).length;
      });
  }

  toggleTopEventCategories() {
    this.topEventCategoriesActive = !this.topEventCategoriesActive;
  }

  toggleEventCategoryOpened(eventCategory: EventCategory & { opened: boolean }) {
    eventCategory.opened = !eventCategory.opened;
  }

  toggleEventCategorySelection(eventCategory: EventCategory) {
    eventCategory.isChecked = !eventCategory.isChecked;

    const delta = eventCategory.isChecked ? +1 : -1;
    if (this.topEventCategories.indexOf(eventCategory) !== -1) {
      this.topEventCategoriesSelectionNumber += delta;
    }

    this.allEventCategories[eventCategory.parentEventCategoryId].selectionNumber += delta;

    if (eventCategory.isChecked) {
      this.selectedEventCategories.push(eventCategory);
    } else {
      this.selectedEventCategories.splice(this.selectedEventCategories.indexOf(eventCategory), 1);
    }

    this.filterChanged.next({ eventCategories: this.selectedEventCategories, applied: false });
  }

  showMore() {
    this.showAllEventCategories = true;
  }

  cancel() {
    this.topEventCategoriesSelectionNumber = 0;
    for (let key in this.allEventCategories) {
      let value = this.allEventCategories[key];

      value.selectionNumber = 0;
      value.subCategories.forEach(c => (c.isChecked = false));
    }

    this.selectedEventCategories = [];

    this.filterChanged.next({ eventCategories: this.selectedEventCategories, applied: false });
  }

  apply() {
    this.filterChanged.next({ eventCategories: this.selectedEventCategories, applied: true });
  }
}
