import {
  Input,
  HostBinding,
  ViewChild,
  OnChanges,
  SimpleChanges,
  ChangeDetectionStrategy,
  Component
} from '@angular/core';
import { AnimateDirective } from '@honoregaming/ui';

@Component({
  selector: 'hg-event-bet-type-item-odds',
  templateUrl: './event-bet-type-item-odds.component.html',
  styleUrls: ['./event-bet-type-item-odds.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventBetTypeItemOddsComponent implements OnChanges {
  @Input()
  odds: number;

  @HostBinding('class.selected')
  @Input()
  selected = false;

  @HostBinding('class.disabled')
  get isDisabled() {
    return this.disabled || !this.odds;
  }

  @Input()
  disabled = false;

  @HostBinding('class.inactive')
  @Input()
  inactive = false;

  @ViewChild(AnimateDirective, { static: false })
  odd: AnimateDirective;

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['odds'] && !changes['odds'].firstChange && !this.disabled && !this.inactive) {
      const previousOdds = changes['odds'].previousValue;
      const currentOdds = changes['odds'].currentValue;
      if (currentOdds > previousOdds) {
        this.odd.animate('up');
      } else if (currentOdds < previousOdds) {
        this.odd.animate('down');
      }
    }
  }
}
