import { ChangeDetectionStrategy, Component, EventEmitter, Input, Output } from '@angular/core';
import { BetCategoryType } from '@honoregaming/types';
import { TopWinBet } from 'projects/core/hg-types/models/top-win-bets';

const ODDS_CATEGORIES = new Set([BetCategoryType.SportsFixedOdds, BetCategoryType.VirtualFixedOdds]);

@Component({
  selector: 'hg-top-win-bets-popup',
  templateUrl: './top-win-bets-popup.component.html',
  styleUrls: ['./top-win-bets-popup.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TopWinBetsPopupComponent {
  @Input() bet!: TopWinBet;

  @Output() readonly closeEvent = new EventEmitter<void>();

  readonly BetCategoryType = BetCategoryType;

  get showOdds(): boolean {
    return ODDS_CATEGORIES.has(this.bet.betSystem.betCategory);
  }

  get showBetLinesCount(): boolean {
    return (
      this.bet.betSystem.betCategory === BetCategoryType.SportsFixedOdds &&
      (this.bet.betSystem.betLines?.length ?? 0) > 1
    );
  }

  closePopup(): void {
    this.closeEvent.emit();
  }
}
