import { Injectable } from '@angular/core';
import { Media } from '@honoregaming/ui';

export interface StickyHeaderParams {
  yOffset: number;
  media: Media;
  countMessages: number;
  eventBetGroupsHeight: number;
  scoreWidgetHeight: number;
  blockEventHeight: number;
  isLiveEvent: boolean;
  hasStatsDisplayed: boolean;
  hostBottomDistance: number;
}

export interface StickyHeaderState {
  isStickyHeader: boolean;
  isStickyFilters: boolean;
  blockEventMobileHeight: number;

  /**
   * When true the caller should capture the score widget's offsetHeight
   * (one-time lazy initialisation on first sticky activation).
   */
  shouldCaptureScoreWidgetHeight: boolean;
}

/**
 * Pure calculation service for sticky-header behaviour.
 *
 * Takes a snapshot of scroll/layout measurements and returns the
 * derived sticky state.  No DOM access, no subscriptions, no
 * change-detection — the component owns all of that.
 */
@Injectable({
  providedIn: 'root'
})
export class EventPageStickyHeaderService {
  private static readonly MESSAGE_HEIGHT = 40; // px per message row
  private static readonly DESKTOP_HEADER_HEIGHT = 150;
  private static readonly TABLET_HEADER_HEIGHT = 70;
  private static readonly MOBILE_HEADER_HEIGHT = 55;
  private static readonly DESKTOP_STICKY_MARGIN = 30;
  private static readonly MIN_EVENT_BET_GROUPS_HEIGHT = 200;
  private static readonly NEAR_BOTTOM_THRESHOLD = 200;

  /**
   * Single entry-point: compute the full sticky state from raw measurements.
   */
  computeStickyState(params: StickyHeaderParams): StickyHeaderState {
    const messagesHeight: number = params.countMessages * EventPageStickyHeaderService.MESSAGE_HEIGHT;

    const state: StickyHeaderState =
      params.media >= Media.lg
        ? this.computeDesktop(params, messagesHeight)
        : this.computeMobileTablet(params, messagesHeight);

    state.shouldCaptureScoreWidgetHeight = state.isStickyHeader && !params.scoreWidgetHeight;

    return state;
  }

  private computeDesktop(params: StickyHeaderParams, messagesHeight: number): StickyHeaderState {
    const { DESKTOP_HEADER_HEIGHT: headerHeight, DESKTOP_STICKY_MARGIN: margin } = EventPageStickyHeaderService;

    const isStickyHeader: boolean = params.yOffset >= headerHeight + messagesHeight + margin;

    const isStickyFilters: boolean =
      isStickyHeader && params.scoreWidgetHeight + headerHeight + messagesHeight <= params.yOffset;

    const blockEventMobileHeight: number = params.hasStatsDisplayed
      ? this.resolveLiveBlockHeight(params.media)
      : params.blockEventHeight - 1;

    return { isStickyHeader, isStickyFilters, blockEventMobileHeight, shouldCaptureScoreWidgetHeight: false };
  }

  private computeMobileTablet(params: StickyHeaderParams, messagesHeight: number): StickyHeaderState {
    const isTablet: boolean = params.media >= Media.md;
    const headerHeight: number = isTablet
      ? EventPageStickyHeaderService.TABLET_HEADER_HEIGHT
      : EventPageStickyHeaderService.MOBILE_HEADER_HEIGHT;

    if (!isTablet && this.isNearBottom(params.hostBottomDistance)) {
      return {
        isStickyHeader: false,
        isStickyFilters: false,
        blockEventMobileHeight: params.hasStatsDisplayed
          ? this.resolveLiveBlockHeight(params.media)
          : params.blockEventHeight + headerHeight,
        shouldCaptureScoreWidgetHeight: false
      };
    }

    const additionalMessagesHeight = isTablet ? messagesHeight : params.isLiveEvent ? 0 : messagesHeight;

    const isStickyHeader: boolean =
      params.eventBetGroupsHeight > EventPageStickyHeaderService.MIN_EVENT_BET_GROUPS_HEIGHT &&
      params.yOffset >= headerHeight + messagesHeight;

    const isStickyFilters: boolean =
      isStickyHeader && params.scoreWidgetHeight + additionalMessagesHeight <= params.yOffset;

    const blockEventMobileHeight: number = params.hasStatsDisplayed
      ? this.resolveLiveBlockHeight(params.media)
      : params.blockEventHeight + headerHeight;

    return { isStickyHeader, isStickyFilters, blockEventMobileHeight, shouldCaptureScoreWidgetHeight: false };
  }

  private resolveLiveBlockHeight(media: Media): number {
    if (media >= Media.lg) {
      return 0;
    }
    return media >= Media.md
      ? EventPageStickyHeaderService.TABLET_HEADER_HEIGHT
      : EventPageStickyHeaderService.MOBILE_HEADER_HEIGHT;
  }

  private isNearBottom(hostBottomDistance: number): boolean {
    return hostBottomDistance + EventPageStickyHeaderService.NEAR_BOTTOM_THRESHOLD < 0;
  }
}
