import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Input,
  ViewChildren,
  QueryList,
  ElementRef,
  Inject,
  PLATFORM_ID,
  NgZone,
  HostBinding,
  Optional,
  OnDestroy
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import {
  ApplicationStateService,
  Async,
  AsyncTrigger,
  DestroySubject,
  delayBetween,
  getUtcNow,
  updateEventBetTypeAfterPush,
  PushService,
  updateEventAfterPush,
  kioskToken,
  CompleteMyBetService,
  BetCategoryConfigurationService,
  BetLinesMapperService
} from '@honoregaming/core';
import { finalize, take, takeUntil } from 'rxjs/operators';
import { Subscription, timer } from 'rxjs';
import {
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  TelemetryService,
  TopMatchsInstantGamesService
} from '@honoregaming/customer-core';
import {
  EventBetType,
  EventBetTypeItem,
  EventStateType,
  EventWithEventBetTypes,
  InstantGame,
  InstantGameProvider,
  Match,
  SelectableEventBetTypeItem,
  SelectedItem
} from '@honoregaming/types';
import { BetSlipBetLinesService, BetSlipLinesInfo, BetSlipService } from '@honoregaming/betslip';
import { I18nService } from '@honoregaming/i18n';
import { Media, MediaService } from '@honoregaming/ui';
import { globalConfiguration } from '@honoregaming/configuration';

@Component({
  selector: 'hg-top-matchs-games',
  templateUrl: './top-matchs-games.component.html',
  styleUrls: ['./top-matchs-games.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TopMatchsGamesComponent extends DestroySubject implements OnInit, OnDestroy {
  @ViewChildren('slideElements')
  slideRefs: QueryList<ElementRef<HTMLElement>>;

  @HostBinding('class.noslide') noSlide: boolean = false;

  @Input()
  slideTimer: number;

  @Input()
  showTimer: boolean;

  baseAssetsPath = this.customerOperatorConfiguration.instantGamesConfiguration?.insaGamesAssetsPath;
  assetsPath: string = '';
  games: (InstantGame & { computedUrl: string })[];

  homePageAnchor =
    this.customerOperatorConfiguration.customization['homepage'] ??
    this.customerOperatorConfiguration.customization['sports-homepage'];

  countDown: number;
  timerCountDown: Subscription;
  topMatchsNumber: number;
  topGamesNumber: number;
  currentIndex: number = this.mediaService?.media < Media.lg ? 0 : 1;

  // Save each tab index while changing tab.
  internalMatchesCurrentIndex: number = this.currentIndex;
  internalInstantGamesCurrentIndex: number = this.currentIndex;

  swipeCoord: [number, number];
  swipeTime: number;
  timerInterval: any;
  betCategoriesOrder = '';
  event: EventWithEventBetTypes<Match>;
  topMatchesOrder: number;
  topGamesOrder: number;
  order: string;
  type: string;

  isFirstSlide = false;
  isLoadingMatchs = false;
  isLoadingGames = false;
  isLoadingOddsEventIds: number[] = [];
  tabMultiCategories = 1;

  topMatchs: EventWithEventBetTypes<Match>[] = [];
  topGames = [];
  slides = [];
  instantGames = [];
  selectedItems: SelectedItem[] = [];
  slidesMatchs = [];

  sportsImagesNumber = [
    { sport: 101, maxCountArray: Array.from(Array(6).keys()) }, // soccer
    { sport: 102, maxCountArray: Array.from(Array(1).keys()) }, // basketball
    { sport: 103, maxCountArray: Array.from(Array(2).keys()) }, // tennis
    { sport: 104, maxCountArray: Array.from(Array(3).keys()) }, // rugby
    { sport: 105, maxCountArray: Array.from(Array(1).keys()) }, // american football
    { sport: 106, maxCountArray: Array.from(Array(1).keys()) }, // badminton
    { sport: 107, maxCountArray: Array.from(Array(1).keys()) }, // baseball
    { sport: 108, maxCountArray: Array.from(Array(1).keys()) }, // dart
    { sport: 109, maxCountArray: Array.from(Array(1).keys()) }, // futsal
    { sport: 110, maxCountArray: Array.from(Array(2).keys()) }, // handball
    { sport: 111, maxCountArray: Array.from(Array(1).keys()) }, // ice hockey
    { sport: 112, maxCountArray: Array.from(Array(1).keys()) }, // snooker
    { sport: 113, maxCountArray: Array.from(Array(2).keys()) }, // table tennis
    { sport: 114, maxCountArray: Array.from(Array(1).keys()) }, // volleyball
    { sport: 1000, maxCountArray: Array.from(Array(1).keys()) }, // Lol
    { sport: 1001, maxCountArray: Array.from(Array(1).keys()) }, // CS
    { sport: 1002, maxCountArray: Array.from(Array(1).keys()) } // Dota
  ];

  private eventBetTypesPushSubscription: Subscription;
  private eventsPushSubscription: Subscription;

  instantGamesBetCategoryPath = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  constructor(
    @Inject(PLATFORM_ID) private platId,
    private zone: NgZone,
    private cdRef: ChangeDetectorRef,
    private betSlipService: BetSlipService,
    private topMatchsInstantGamesService: TopMatchsInstantGamesService,
    private applicationStateService: ApplicationStateService,
    private i18nService: I18nService,
    @Optional() private mediaService: MediaService,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration,
    protected pushService: PushService,
    private betCategoryConfigurationService: BetCategoryConfigurationService,
    @Inject(kioskToken) public isKiosk: boolean,
    private completeMyBetService: CompleteMyBetService,
    private telemetryService: TelemetryService,
    private betLinesMapperService: BetLinesMapperService,
    private betSlipBetLinesService: BetSlipBetLinesService
  ) {
    super();
  }

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  ngOnInit() {
    const regex = new RegExp(/^(https?:\/\/[^\/]+)/); // Permet de matcher l'url de base
    const matches = regex.exec(globalConfiguration.assetsPath);
    this.assetsPath = matches ? matches[0] : '';

    this.topGamesOrder = Number(this.homePageAnchor.topInstantGamesOrder);
    this.topMatchesOrder = Number(this.homePageAnchor.topMatchsOrder);
    this.getTopMatchs();

    if (!this.isKiosk) {
      this.getTopInstantGames();
    }
    this.loadBetCategoriesOrder();
    this.clickOnTab(1);

    if (this.slideTimer && isPlatformBrowser(this.platId)) {
      this.applicationStateService.isReady$.subscribe(() => {
        if (this.timerCountDown) {
          this.timerCountDown.unsubscribe();
        }

        this.timerCountDown = timer(0, 1000)
          .pipe(takeUntil(this.destroy$))
          .subscribe(_ => {
            this.countDown = delayBetween(getUtcNow(), this.event.expectedStart);
            this.zone.run(() => this.cdRef.markForCheck());
          });
      });
    }

    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe((betSlipLinesInfo: BetSlipLinesInfo) => {
      this.selectedItems = this.betLinesMapperService.betLinesToSelectedItems(betSlipLinesInfo.lines);
      this.cdRef.markForCheck();
    });

    this.listenOnLoadingOddsChanges();
  }

  ngOnDestroy() {
    super.ngOnDestroy();

    this.eventBetTypesPushSubscription?.unsubscribe();
    this.eventsPushSubscription?.unsubscribe();

    this.pushService.subscribeToEvents([]);
    this.pushService.subscribeToOdds([], []);
  }

  private loadBetCategoriesOrder() {
    if (this.customerOperatorConfiguration.customization[this.betCategoriesOrder]) {
      this.order = this.customerOperatorConfiguration.customization[this.betCategoriesOrder].map(x => {
        x = Number(x.order);

        return x;
      });
    }
  }

  @Async()
  getTopMatchs() {
    this.isLoadingMatchs = true;
    this.topMatchsInstantGamesService
      .getTopMatchs()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoadingMatchs = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(results => {
        this.topMatchs = results;
        this.topMatchsNumber = results?.length;

        if (this.topMatchsNumber === 0) {
          this.clickOnTab(2);
        }

        if (!this.topGames && !this.topMatchesOrder) {
          this.clickOnTab(1);
        }

        if (this.slides?.length) {
          this.slides = [];
        }

        if (this.slideRefs?.length) {
          this.slideRefs.forEach(x => x.nativeElement.classList.remove('prev', 'next', 'next-next', 'prev-prev'));
        }

        this.topMatchs.forEach(t => {
          const numberImages = this.sportsImagesNumber.find(s => s.sport === t.entryPointId)?.maxCountArray;
          const randomNumber = Math.floor(Math.random() * (numberImages?.length - 1));
          if (!isNaN(randomNumber) && randomNumber >= 0) {
            this.slides.push(numberImages[randomNumber] + 1);

            const index = numberImages.indexOf(randomNumber);
            numberImages.splice(index, 1);
          } else {
            this.slides.push(1);
          }
        });

        this.slides.map((x, i) => {
          if (isNaN(x) || x === undefined) {
            this.slides[i] = 1;
          }
        });

        setTimeout(() => this.initPreviousNext(), 0);
        this.handleSlides();

        this.subscribeToPushChanges();
        this.registerToPushChanges();

        this.cdRef.markForCheck();
      });
  }

  subscribeToPushChanges() {
    if (!this.eventBetTypesPushSubscription) {
      this.eventBetTypesPushSubscription = this.pushService.eventBetTypeChanged$
        .pipe(takeUntil(this.destroy$))
        .subscribe(changed => {
          this.topMatchs.forEach(x => {
            const index = x.eventBetTypes?.findIndex(y => y.id === changed.eventBetTypeId);
            if (index >= 0) {
              if (changed.active === false) {
                x.eventBetTypes[index].bettingAllowed = false; // HACK until better solution
              } else {
                updateEventBetTypeAfterPush(x.eventBetTypes[index], changed);
              }

              x.eventBetTypes[index] = { ...x.eventBetTypes[index] };
              this.cdRef.markForCheck();
            }
          });
        });
    }

    if (!this.eventsPushSubscription) {
      this.eventsPushSubscription = this.pushService.eventChanged$.pipe(takeUntil(this.destroy$)).subscribe(changed => {
        let eventChangedToLiveState = false;

        this.topMatchs.forEach(x => {
          if (x.id === changed.eventId) {
            x = updateEventAfterPush(x, x.eventBetTypes, changed);
            if (
              changed.changes['state'] &&
              changed.changes['state'] !== EventStateType.AboutToStart &&
              changed.changes['state'] !== EventStateType.Undisputed &&
              changed.changes['state'] !== EventStateType.Delayed
            ) {
              eventChangedToLiveState = true;
            }

            this.cdRef.markForCheck();
          }
        });

        if (eventChangedToLiveState) {
          this.onEventChangedToLiveState();
        }
      });
    }
  }

  onEventChangedToLiveState() {
    this.getTopMatchs();
  }

  registerToPushChanges() {
    this.pushService.subscribeToEvents(this.topMatchs?.map(e => e.id) || [], 'topMatchs');
    this.pushService.subscribeToOdds(
      this.topMatchs?.length
        ? this.topMatchs
            ?.filter(x => x.eventBetTypes)
            .map(e => e.eventBetTypes.map(ebt => ebt.id))
            .reduce((a, b) => a?.concat(b), [])
        : [],
      [],
      'topMatchs'
    );
  }

  trackEventBetType(_index: number, eventBetType: EventBetType) {
    return eventBetType.id;
  }

  getTopInstantGames() {
    this.isLoadingGames = true;

    this.topMatchsInstantGamesService
      .getTopInstantGames()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoadingGames = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(results => {
        this.topGames = results;
        this.topGamesNumber = results?.length;

        this.instantGames = Array(this.topGamesNumber);

        this.games = this.topGames.map(g => {
          let url = `/${this.instantGamesBetCategoryPath}/` + g.url;
          if (g.provider === InstantGameProvider.InsaGames) {
            return {
              ...g,
              computedUrl: `/${this.instantGamesBetCategoryPath}/ig/` + g.url,
              imageUrl: g.imageUrl || `${this.baseAssetsPath}${g.url}/thumbnail.png`
            };
          } else if (g.provider === InstantGameProvider.EveryMatrix) {
            url = `/${this.instantGamesBetCategoryPath}/em/` + g.url;
          } else if (g.provider === InstantGameProvider.GameTech) {
            return {
              ...g,
              computedUrl: `/${this.instantGamesBetCategoryPath}/gt/` + g.url,
              imageUrl: `${this.assetsPath}/instant-game-providers/${g.imageUrl}`
            };
          } else if (g.provider === InstantGameProvider.AviatorLlc) {
            return {
              ...g,
              computedUrl: `/${this.instantGamesBetCategoryPath}/` + g.url
            };
          } else if (g.provider === InstantGameProvider.BoomingGames) {
            return {
              ...g,
              computedUrl: `/${this.instantGamesBetCategoryPath}/` + g.url,
              imageUrl: g.imageUrl
            };
          }

          return { ...g, computedUrl: url };
        });

        this.topGames = this.games;
        this.handleSlides();

        setTimeout(() => this.initPreviousNext(), 0);

        this.cdRef.markForCheck();
      });
  }

  public toggleBet(event: Event, topMatch: Match, ebt: EventBetType, item: SelectableEventBetTypeItem) {
    event.preventDefault();
    event.stopImmediatePropagation();

    if (
      item.odds <= 1 ||
      !ebt.active ||
      !ebt.bettingAllowed ||
      !item.active ||
      !item.bettingAllowed ||
      this.isTopMatchCompletionDisabled(topMatch, item)
    ) {
      return;
    }

    const isSelected: boolean = !this.isSelectedItem(item.id);

    if (isSelected) {
      this.telemetryService.trackEvent('top_matchs_games_click_on_eventbettypeitem', {
        matchName: topMatch.homeTeamName + ' - ' + topMatch.awayTeamName,
        entryPointId: topMatch.entryPointId,
        eventBetType: ebt.name,
        eventBetTypeItem: item.shortName,
        odds: item.odds
      });
    }

    this.betSlipBetLinesService
      .toggleEventBetTypeItem({ ...topMatch, expectedStart: new Date(topMatch.expectedStart) }, ebt, item, isSelected)
      .pipe(take(1))
      .subscribe((selected: boolean) => {
        if (item.selected && !selected) {
          this.selectedItems = this.selectedItems.filter(
            (selectedItem: SelectedItem) => selectedItem.eventBetTypeItemId !== item.id
          );
          this.cdRef.markForCheck();
        }
      });
  }

  trackEventBetTypeItem(_index: number, eventBetTypeItem: EventBetTypeItem) {
    return eventBetTypeItem.id;
  }

  clickOnTab(number: number, fromCustomerInput = false) {
    this.tabMultiCategories = number;

    this.currentIndex =
      this.tabMultiCategories === this.topMatchesOrder
        ? this.internalMatchesCurrentIndex
        : this.internalInstantGamesCurrentIndex;

    this.startOrRestartTimer();
    setTimeout(() => this.initPreviousNext(), 0);

    this.isFirstSlide = false;
    this.cdRef.markForCheck();

    if (fromCustomerInput) {
      this.telemetryService.trackEvent('top_matchs_games_click_on_tab', {
        tab: number === this.topMatchesOrder ? 'matchs' : 'instant_games'
      });
    }
  }

  clickOnGame(game: InstantGame, index: number) {
    this.telemetryService.trackEvent('top_matchs_games_click_on_game', {
      game: game.name,
      position: index
    });
  }

  clickOnMatch(match: EventWithEventBetTypes<Match>, index: number) {
    this.telemetryService.trackEvent('top_matchs_games_click_on_match', {
      match: match.homeTeamName + ' - ' + match.awayTeamName,
      position: index
    });
  }

  isSelectedItem(eventBetTypeItemId: number): boolean {
    return !!this.selectedItems.find((item: SelectedItem) => item.eventBetTypeItemId === eventBetTypeItemId);
  }

  isTopMatchCompletionDisabled(match: Match, item: SelectableEventBetTypeItem): boolean {
    return this.completeMyBetService.isTopMatchCompletionDisabled(this.selectedItems, match, item);
  }

  private handleSlides() {
    // min 5 slides
    this.slidesMatchs = this.duplicateArrayToMin5Items(this.slides);
    this.topMatchs = this.duplicateArrayToMin5Items(this.topMatchs);
    this.topGames = this.duplicateArrayToMin5Items(this.topGames);
    this.cdRef.markForCheck();
  }

  duplicateArrayToMin5Items = <T>(input: T[]): T[] =>
    input.length === 2
      ? [...input, ...input, ...input]
      : input.length <= 4 && input.length !== 1
      ? [...input, ...input]
      : input;

  initPreviousNext() {
    const sliderArray = this.slideRefs.toArray();

    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length - 1) % sliderArray.length]?.nativeElement,
      'prev'
    );
    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length + 1) % sliderArray.length]?.nativeElement,
      'next'
    );
    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length + 2) % sliderArray.length]?.nativeElement,
      'next-next'
    );
    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length - 2) % sliderArray.length]?.nativeElement,
      'prev-prev'
    );
  }

  startOrRestartTimer() {
    if (isPlatformBrowser(this.platId) && this.slideTimer && (this.slides.length > 3 || this.topGames.length > 3)) {
      this.zone.runOutsideAngular(() => {
        clearInterval(this.timerInterval);

        this.timerInterval = setInterval(
          () => this.zone.run(() => this.navTo((this.currentIndex + 1) % this.slides.length)),
          this.slideTimer * 1e3
        );
      });
    }
  }

  initialPositions = {
    active: 0,
    next: 0,
    'next-next': 0,
    prev: 0,
    'prev-prev': 0
  };

  initialSlideWidth = 0;

  swipe(e: TouchEvent, event: 'start' | 'move' | 'end', type: string): void {
    const classes = ['next', 'prev', 'active', 'next-next', 'prev-prev'];

    if (this.slides.length <= 1) {
      return;
    }

    const coord: [number, number] = [e.changedTouches[0].pageX, e.changedTouches[0].pageY];
    const time = new Date().getTime();
    let topType = [];
    type === 'games' ? (topType = this.topGames) : (topType = this.topMatchs);

    if (topType.length >= 3 && this.mediaService?.media < Media.lg) {
      if (event === 'start') {
        this.swipeCoord = coord;
        this.swipeTime = time;
        this.initialSlideWidth = this.getElementByClass('active').getBoundingClientRect().width;
        classes.forEach(c => {
          this.initialPositions[c] = new DOMMatrix(getComputedStyle(this.getElementByClass(c)).transform).m41;
        });

        this.slideRefs
          .filter(x => classes.some(c => x.nativeElement.classList.contains(c)))
          .forEach(x => x.nativeElement.classList.add('notransition'));
      } else if (event === 'move') {
        classes.forEach(c => {
          var dist = Math.max(Math.min(this.initialSlideWidth, coord[0] - this.swipeCoord[0]), -this.initialSlideWidth);
          this.getElementByClass(c).style.transform = `translateX(${this.initialPositions[c] + dist}px)`;
        });
      } else if (event === 'end') {
        const direction = [coord[0] - this.swipeCoord[0], coord[1] - this.swipeCoord[1]];
        this.slideRefs
          .filter(x => classes.some(c => x.nativeElement.classList.contains(c)))
          .forEach(x => {
            x.nativeElement.classList.remove('notransition');
            x.nativeElement.style.transform = '';
          });
        const duration = time - this.swipeTime;
        // swipe duration is long enought (500ms), distance is long enough (20px) and horizontal enough (~20° max)
        if (duration > 50 && Math.abs(direction[0]) > 20 && Math.abs(direction[0]) > Math.abs(direction[1] * 2)) {
          if (direction[0] > 0) {
            this.navTo(this.currentIndex === 0 ? topType.length - 1 : this.currentIndex - 1, true);
          } else {
            this.navTo((this.currentIndex + 1) % topType.length);
          }
        }
      }
    }
  }

  getElementByClass = (className: string): HTMLElement =>
    this.slideRefs.filter(x => x.nativeElement.classList.contains(className))?.[0]?.nativeElement;

  fakeScope = {};

  disableNav = false;
  navigate(direction: string, type: string) {
    let slides: any[];

    type === 'matchs' ? (slides = this.topMatchs) : (slides = this.topGames);

    if (direction === 'next') {
      this.navTo((this.currentIndex + 1) % slides.length);
    } else {
      this.navTo(this.currentIndex === 0 ? slides.length - 1 : this.currentIndex - 1, true);
    }
    this.disableNav = true;
    setTimeout(() => {
      this.disableNav = false;
      this.cdRef.markForCheck();
    }, 150);
  }

  navTo(index: number, back = false) {
    this.isFirstSlide = true;
    if (this.currentIndex === index) {
      return;
    }

    this.startOrRestartTimer();

    const prevClass = back ? 'next' : 'prev';
    const nextClass = back ? 'prev' : 'next';
    const classes = ['next', 'prev', 'next-next', 'prev-prev'];

    const sliderArray = this.slideRefs.toArray();

    const next = sliderArray[index];

    if (
      [1, sliderArray.length - 1].indexOf((this.currentIndex - index + sliderArray.length) % sliderArray.length) > -1
    ) {
      // mobile or only step (so full transition of 4 slides)
      setTimeout(() => {
        this.slideRefs.forEach(x => {
          if (x.nativeElement.classList.contains('next-next') && back) {
            x.nativeElement.classList.add('notransition');
          } else {
            x.nativeElement.classList.remove('notransition');
          }
          classes.forEach(c => x.nativeElement.classList.remove(c));
        });
        sliderArray[(index + sliderArray.length - 1) % sliderArray.length].nativeElement.classList.add('prev');
        sliderArray[(index + sliderArray.length + 1) % sliderArray.length].nativeElement.classList.add('next');
        sliderArray[(index + sliderArray.length - 2) % sliderArray.length].nativeElement.classList.add('prev-prev');
        sliderArray[(index + sliderArray.length + 2) % sliderArray.length].nativeElement.classList.add('next-next');
        if (!back) {
          sliderArray[(index + sliderArray.length + 2) % sliderArray.length].nativeElement.classList.add(
            'notransition'
          );
        } else {
          sliderArray[(index + sliderArray.length - 2) % sliderArray.length].nativeElement.classList.add(
            'notransition'
          );
        }
      });
    } else {
      // More than one step transition, so desktop and only 2 slides transition
      sliderArray
        .filter(
          x => x.nativeElement.classList.contains(`${nextClass}`) || x.nativeElement.classList.contains(`${prevClass}`)
        )
        .forEach(x => {
          this.removeClassesWithoutTransition(x.nativeElement, ...classes);
        });

      this.addClassesWithoutTransition(next.nativeElement, nextClass);
      this.addClassesWithoutTransition(
        sliderArray[(index + sliderArray.length - 1) % sliderArray.length].nativeElement,
        'prev'
      );
      this.addClassesWithoutTransition(
        sliderArray[(index + sliderArray.length + 1) % sliderArray.length].nativeElement,
        'next'
      );
      this.addClassesWithoutTransition(next.nativeElement, nextClass);
    }

    setTimeout(() => {
      const cur = sliderArray[this.currentIndex];

      this.currentIndex = index;

      if (this.tabMultiCategories === this.topMatchesOrder) {
        this.internalMatchesCurrentIndex = this.currentIndex;
      }

      if (this.tabMultiCategories === this.topGamesOrder) {
        this.internalInstantGamesCurrentIndex = this.currentIndex;
      }

      next.nativeElement.classList.remove(nextClass);
      cur.nativeElement.classList.add(prevClass);
      this.cdRef.markForCheck();
    });
  }

  private addClassesWithoutTransition(element: HTMLElement, ...cssClasses: string[]) {
    if (element) {
      element.classList.add('notransition');
      element.classList.add(...cssClasses);
      // assignation to make the browser update the element position before next animation loop
      this.fakeScope = element.offsetWidth;
      element.classList.remove('notransition');
    }
  }

  private removeClassesWithoutTransition(element: HTMLElement, ...cssClasses: string[]) {
    if (element) {
      element.classList.add('notransition');
      element.classList.remove(...cssClasses);
      // assignation to make the browser update the element position before next animation loop
      this.fakeScope = element.offsetWidth;
      element.classList.remove('notransition');
    }
  }

  private listenOnLoadingOddsChanges(): void {
    this.betSlipBetLinesService.isLoadingOddsEventIds$
      .pipe(takeUntil(this.destroy$))
      .subscribe((isLoadingOddsEventIds: number[]) => {
        this.isLoadingOddsEventIds = isLoadingOddsEventIds;
        this.cdRef.markForCheck();
      });
  }
}
