import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { globalConfiguration } from '@honoregaming/configuration';
import { buildQueryString, Cacheable } from '@honoregaming/core';
import { TopWinBet, TopWinScope } from 'projects/core/hg-types/models/top-win-bets';

@Injectable({ providedIn: 'root' })
export class TopWinBetService {
  constructor(private readonly httpClient: HttpClient) {}

  @Cacheable()
  getTopWinBets(scope?: TopWinScope): Observable<TopWinBet[]> {
    return this.httpClient.get<TopWinBet[]>(
      `${globalConfiguration.apiBettingBaseUrl}betting/top-winning${buildQueryString({
        scope: scope
      })}`
    );
  }
}
