import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { PushService, Async, BroadcastingService, BetLinesMapperService } from '@honoregaming/core';
import { finalize, takeUntil } from 'rxjs/operators';
import { Match, BetCategoryType, SelectableEventBetTypeItem, EventWithEventBetTypes } from '@honoregaming/types';
import { BetSlipBetLinesService, BetSlipService } from '@honoregaming/betslip';
import { EventsWithEventBetTypesComponentBase } from '@honoregaming/sports-ui';
import { EventsService, FetchEventBetTypesMode, EventsMapperService } from '@honoregaming/events';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-search-container',
  templateUrl: './search.container.html',
  styleUrls: ['./search.container.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SearchComponent extends EventsWithEventBetTypesComponentBase implements OnInit {
  searchTerm: string;
  page: number;
  hasMore = true;
  loading: boolean;

  private pageSize = 10;

  constructor(
    private route: ActivatedRoute,
    private eventsService: EventsService,
    protected i18nService: I18nService,
    protected betSlipService: BetSlipService,
    protected pushService: PushService,
    protected cdRef: ChangeDetectorRef,
    protected bcService: BroadcastingService,
    protected eventsMapperService: EventsMapperService,
    protected betLinesMapperService: BetLinesMapperService,
    protected betSlipBetLinesService: BetSlipBetLinesService
  ) {
    super(
      i18nService,
      betSlipService,
      pushService,
      cdRef,
      bcService,
      eventsMapperService,
      betLinesMapperService,
      betSlipBetLinesService
    );
  }

  ngOnInit() {
    super.ngOnInit();
    this.route.params.subscribe(params => {
      this.page = 0;
      this.searchTerm = params['search'];
      this.events = [];
      this.loadSearchResult();
    });
  }

  @Async()
  loadSearchResult(): void {
    this.loading = true;

    this.eventsService
      .searchEvents<Match>(
        this.searchTerm,
        [BetCategoryType.SportsFixedOdds],
        this.page++,
        this.pageSize,
        FetchEventBetTypesMode.Default
      )
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        searchResult => {
          this.events = [...this.events, ...searchResult.result];
          this.hasMore = searchResult.hasMore;

          this.subscribeToPushChanges();
          this.subscribeToBetSlip();
          this.registerToPushChanges();
        },
        _ => {
          this.events = [];
          this.hasMore = false;
        }
      );
  }

  trackMatch(_index, match: Match) {
    return match.id;
  }

  onBetSelectionChanged(
    event: EventWithEventBetTypes<Match>,
    selection: {
      item: SelectableEventBetTypeItem;
      selected: boolean;
    }
  ) {
    this.toggleEventBetTypeItem(event, event.eventBetTypes[0], selection);
  }
}
