import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
  name: 'hgBetTypeContext',
  pure: false
})
export class BetTypeContextPipe implements PipeTransform {
  transform(betTypeContext: string): string {
    if (!betTypeContext) {
      return null;
    }

    const json = JSON.parse(betTypeContext);
    const keys = Object.keys(json);

    if (keys && keys.length) {
      // priorize 'totals' key over the random first found
      const totals = keys.find(e => e == 'total');
      let value = null;

      if (!!totals) {
        value = json[totals];
      } else {
        value = json[keys[0]];
      }

      if (value.includes('sr:')) {
        return value.split(':').slice(-1)[0];
      }

      return value;
    }

    return null;
  }
}
