import { Component, ChangeDetectionStrategy } from '@angular/core';
import { trigger, transition, animate, style } from '@angular/animations';
import { EventWithEventBetTypeComponent } from '@honoregaming/customer-ui';

@Component({
  selector: 'hg-incoming-live-event-with-event-bet-type',
  templateUrl: './incoming-live-event-with-event-bet-type.component.html',
  styleUrls: ['./incoming-live-event-with-event-bet-type.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('disabled', [
      transition('void => *', [
        style({ opacity: '0', transform: 'scale(0)' }),
        animate('0.1s ease-in', style({ opacity: '1', transform: 'scale(1)' }))
      ]),
      transition('* => void', animate('0.1s ease-in', style({ opacity: '0', transform: 'scale(0)' })))
    ])
  ]
})
export class IncomingLiveEventWithEventBetTypeComponent extends EventWithEventBetTypeComponent {}
